/// Tope de una subida de imagen. Una radiografía o un PDF de laboratorio caben
/// de sobra; por encima es casi seguro un error o un abuso.
pub(crate) const MAX_SUBIDA: usize = 25 * 1024 * 1024;

/// La política de contenido de la APLICACIÓN. Ver [`cabeceras_de_seguridad`].
const CSP: &str = "default-src 'self'; \
                   script-src 'self'; \
                   style-src 'self'; \
                   img-src 'self' data:; \
                   font-src 'self' data:; \
                   connect-src 'self'; \
                   object-src 'none'; \
                   base-uri 'self'; \
                   form-action 'self'; \
                   frame-ancestors 'none'";

/// Cabeceras que van en TODA respuesta.
///
/// Es el respaldo sistémico que no había: `grep nosniff` sobre el repositorio no
/// devolvía nada, así que la única defensa contra que el navegador reinterprete
/// un tipo era que el tipo estuviera bien — y no lo estaba.
///
/// La CSP máxima —`default-src 'none'; sandbox`— sigue yendo aparte, en la
/// respuesta que sirve archivos subidos: ahí están los bytes de un tercero y ahí
/// puede cerrarse todo sin romper nada, porque la interfaz nunca sale por ese
/// extremo. Lo de aquí es la política de la APLICACIÓN, que es otra cosa.
///
/// # La CSP: probada contra el Angular compilado, no copiada de una lista
///
/// - **`script-src 'self'`, sin `'unsafe-inline'` ni `'unsafe-eval'`.** Es la que
///   para un XSS. Para que se pudiera poner hubo que apagar `inlineCritical` en
///   `angular.json`: emitía `onload="this.media='all'"` en la hoja de estilos —un
///   manejador en línea, o sea script—, y con esta directiva el navegador no lo
///   ejecuta, la hoja se queda en `media="print"` y la aplicación se ve SIN
///   ESTILOS *sin dar un solo error*.
/// - **`style-src 'self'`, CERRADO el 2026-08-08.** Llevó `'unsafe-inline'`
///   mientras hubo Angular: aquel escribía estilos en tiempo de ejecución y
///   usaba atributos `style="…"`, y un nonce no lo arreglaba —vale para
///   elementos `<style>`, no para atributos `style`—. Retirado el SPA, la razón
///   desapareció: el panel no escribe ni uno. Es la puerta que
///   `piezas::barras` dejó preparada al dibujarse en SVG en vez de con
///   `style="width:X%"`, y la que `ningun_panel_escribe_estilos_en_linea`
///   vigilaba esperando este día.
/// - **`default-src 'self'` se pudo cerrar porque el `index.html` dejó de salir a
///   `fonts.googleapis.com`.** Inter viaja ahora dentro del paquete. Eso no era
///   solo un problema de CSP: cada carga le contaba a un tercero que alguien está
///   usando una historia clínica, desde qué IP y a qué hora.
/// - **Nada de HSTS aquí**: el TLS termina en el proxy, que es quien puede
///   prometerlo con conocimiento de causa.
async fn cabeceras_de_seguridad(
    peticion: axum::extract::Request,
    siguiente: axum::middleware::Next,
) -> Response {
    let mut r = siguiente.run(peticion).await;
    let h = r.headers_mut();
    // No reinterpretes el tipo que declaro.
    h.insert(header::X_CONTENT_TYPE_OPTIONS, header::HeaderValue::from_static("nosniff"));
    // Nadie enmarca esta aplicación: sin esto, un sitio ajeno puede ponerla en un
    // iframe y engañar a quien la usa para que pulse donde no cree.
    h.insert(header::X_FRAME_OPTIONS, header::HeaderValue::from_static("DENY"));
    // Y la ruta de una historia clínica no viaja como `Referer` a terceros.
    h.insert(
        header::REFERRER_POLICY,
        header::HeaderValue::from_static("strict-origin-when-cross-origin"),
    );
    // La respuesta que sirve un archivo subido ya trae la suya, MÁS estricta
    // (`default-src 'none'; sandbox`). No se le pisa: quien la puso sabía que ahí
    // podía cerrar del todo, y esta es más permisiva por necesidad.
    if !h.contains_key(header::CONTENT_SECURITY_POLICY) {
        h.insert(header::CONTENT_SECURITY_POLICY, header::HeaderValue::from_static(CSP));
    }
    r
}

pub fn router(estado: Estado) -> Router {
    Router::new()
        .route("/api/acceso", post(acceso))
        // El segundo paso. Va SIN sesión —quien llega aquí todavía no la
        // tiene— y sin capacidad: lo que autoriza es el token pendiente.
        .route("/api/2fa/verificar", post(verificar_2fa))
        .route("/api/salir", post(salir))
        // La contraseña PROPIA, cualquier rol. Va aquí y no bajo `/api/admin`
        // porque no administra a nadie: es la única contraseña que uno puede
        // cambiar sin permiso de gestión.
        .route("/api/mi-clave", post(mi_clave))
        .route("/api/salir-todo", post(salir_todo))
        .route("/api/yo", get(yo))
        .route("/api/demo", get(demo))
        .route("/api/pacientes", get(listar_pacientes).post(crear_paciente))
        .route("/api/pacientes/{id}", get(obtener_paciente).put(actualizar_paciente))
        .route("/api/pacientes/{id}/antecedentes", put(actualizar_antecedentes_paciente))
        .route("/api/pacientes/{id}/historias", get(listar_historias_paciente))
        .route("/api/pacientes/{id}/accesos", get(accesos_paciente))
        // DIVIPOLA, para el selector de municipio (#16/#77).
        .route("/api/municipios", get(listar_municipios))
        .route("/api/acceso/verificar", get(verificar_acceso))
        .route("/api/historias", post(crear_historia))
        .route(
            "/api/historias/{id}",
            get(obtener_historia).put(actualizar_historia).delete(eliminar_historia),
        )
        .route("/api/historias/{id}/firmar", post(firmar_historia))
        .route("/api/historias/{id}/verificar-firma", get(verificar_firma_historia))
        .route("/api/historias/paciente/{id}/contexto", get(contexto_paciente))
        // Documentos clínicos: una sola familia de rutas para todos los tipos
        // (evolución, epicrisis, interconsulta, …); el tipo va como filtro/campo.
        .route("/api/documentos", get(listar_documentos).post(crear_documento))
        .route(
            "/api/documentos/{id}",
            get(obtener_documento).put(actualizar_documento).delete(eliminar_documento),
        )
        .route("/api/documentos/{id}/firmar", post(firmar_documento))
        .route("/api/urgencias/cola", get(urgencias_cola))
        .route(
            "/api/recien-nacidos",
            get(recien_nacidos_listar).post(recien_nacidos_crear),
        )
        // El bloque de enfermería (#249). Cuatro módulos, cuatro prefijos: el
        // catálogo los licencia por separado y la licencia se comprueba por la
        // ruta, así que una IPS puede comprar el MAR sin el plan de cuidados.
        .route("/api/enfermeria/notas", get(enfermeria_notas).post(enfermeria_nota_nueva))
        .route("/api/enfermeria/planes", get(enfermeria_planes).post(enfermeria_plan_nuevo))
        .route(
            "/api/enfermeria/administraciones",
            get(enfermeria_hoja).post(enfermeria_administrar),
        )
        .route("/api/enfermeria/administraciones/{id}/anular", post(enfermeria_anular))
        .route("/api/enfermeria/kardex", get(enfermeria_kardex))
        .route("/api/defunciones", get(defunciones_listar).post(defunciones_certificar))
        .route("/api/defunciones/{id}/anular", post(defunciones_anular))
        .route("/api/censo", get(censo_del_dia))
        .route(
            "/api/anestesia/valoraciones",
            get(anestesia_valoraciones).post(anestesia_valorar),
        )
        .route(
            "/api/anestesia/recuperaciones",
            get(anestesia_recuperaciones).post(anestesia_recibir),
        )
        .route("/api/anestesia/recuperaciones/{id}/salida", post(anestesia_salida))
        // Los cuatro programas de P&P. Prefijos distintos porque se licencian
        // por separado; el manejador es el mismo y el programa sale de la ruta,
        // no de un parámetro que el cliente elija.
        // CADA ruta bajo el prefijo de SU programa, y ninguna suelta. La primera
        // versión tenía `/api/pyp/controles` y `/api/pyp/inscripciones/{id}/egresar`
        // fuera de todo prefijo, así que se servían SIN PUERTA DE LICENCIA — lo
        // cazó `ninguna_ruta_de_modulo_se_queda_sin_licencia`. Y al partirlas por
        // programa se cerró de paso un agujero mayor: ahora el programa sale de
        // la RUTA, y el manejador comprueba que la inscripción sea de ése, así
        // que quien tiene licencia de vacunación no puede controlar un prenatal.
        .route("/api/pyp/prenatal", get(pyp_prenatal).post(pyp_inscribir_prenatal))
        .route("/api/pyp/prenatal/controles", post(pyp_controlar_prenatal))
        .route("/api/pyp/prenatal/egresar/{id}", post(pyp_egresar_prenatal))
        .route("/api/pyp/crecimiento", get(pyp_crecimiento).post(pyp_inscribir_crecimiento))
        .route("/api/pyp/crecimiento/controles", post(pyp_controlar_crecimiento))
        .route("/api/pyp/crecimiento/egresar/{id}", post(pyp_egresar_crecimiento))
        .route("/api/pyp/reproductiva", get(pyp_reproductiva).post(pyp_inscribir_reproductiva))
        .route("/api/pyp/reproductiva/controles", post(pyp_controlar_reproductiva))
        .route("/api/pyp/reproductiva/egresar/{id}", post(pyp_egresar_reproductiva))
        .route("/api/pyp/vacunas", get(pyp_vacunas).post(pyp_aplicar))
        // Habilitación. CADA ruta bajo el prefijo de su módulo: es la lección de
        // las dos rutas de P&P que se quedaron fuera de todo prefijo.
        .route("/api/habilitacion/equipos", get(hab_equipos).post(hab_crear_equipo))
        .route("/api/habilitacion/equipos/mantenimientos", post(hab_mantenimiento))
        .route("/api/habilitacion/comites", get(hab_comites).post(hab_crear_comite))
        .route("/api/habilitacion/comites/sesiones", post(hab_sesion))
        .route("/api/habilitacion/infecciones", get(hab_iaas).post(hab_reportar_iaas))
        .route("/api/habilitacion/infecciones/{id}/notificar", post(hab_notificar))
        .route("/api/habilitacion/indicadores", get(hab_indicadores))
        // Los últimos cinco. La nota de trabajo social entra por SU ruta, con el
        // tipo puesto por el servidor, igual que las de enfermería.
        .route("/api/trabajo-social/notas", get(ts_notas).post(ts_nota_nueva))
        .route("/api/teleconsultas", get(tele_listar).post(tele_registrar))
        .route("/api/turnos", get(turnos_listar).post(turnos_programar))
        .route("/api/turnos/{id}", delete(turnos_quitar))
        .route("/api/banco-sangre", get(sangre_unidades).post(sangre_registrar))
        .route("/api/banco-sangre/{id}/tamizaje", post(sangre_tamizar))
        .route("/api/banco-sangre/transfusiones", get(sangre_transfusiones).post(sangre_transfundir))
        .route("/api/banco-sangre/transfusiones/{id}/reaccion", post(sangre_reaccion))
        .route("/api/urgencias/triage", post(urgencias_triage))
        .route("/api/urgencias/{id}/egreso", put(urgencias_egreso))
        .route("/api/hospitalizacion", get(hosp_listar))
        .route("/api/hospitalizacion/camas", get(hosp_camas))
        .route("/api/hospitalizacion/medicos", get(hosp_medicos))
        .route("/api/hospitalizacion/ingresar", post(hosp_ingresar))
        .route("/api/hospitalizacion/{id}/egreso", put(hosp_egreso))
        .route("/api/nutricion/valoraciones", get(nutri_listar).post(nutri_crear))
        .route(
            "/api/nutricion/valoraciones/{id}",
            get(nutri_obtener).put(nutri_actualizar).delete(nutri_eliminar),
        )
        .route(
            "/api/nutricion/valoraciones/{id}/plan",
            get(nutri_plan).post(nutri_crear_plan),
        )
        .route("/api/nutricion/planes/{id}", put(nutri_actualizar_plan))
        .route("/api/rehabilitacion/planes", get(rehab_listar).post(rehab_crear))
        .route(
            "/api/rehabilitacion/planes/{id}",
            get(rehab_obtener).put(rehab_actualizar),
        )
        .route(
            "/api/rehabilitacion/planes/{id}/sesiones",
            get(rehab_sesiones).post(rehab_crear_sesion),
        )
        .route("/api/rehabilitacion/sesiones/{id}", put(rehab_actualizar_sesion))
        // LAS DOS FORMAS, CON BARRA FINAL Y SIN ELLA, y no es adorno: axum 0.8
        // quitó la redirección automática, y `consentimiento.component.ts:242`
        // pide `/api/consentimiento/` — la ÚNICA llamada del frontal que la lleva
        // (comprobado con grep sobre `frontend/src`). Registrando solo la forma
        // sin barra, la pantalla habría dado 404 contra el binario mientras
        // seguía funcionando contra el Python, que sí redirige. Es el fallo que
        // ninguna prueba de módulo ve y que solo aparece abriendo la aplicación
        // (directiva 28).
        .route("/api/consentimiento", get(consent_listar).post(consent_crear))
        .route("/api/consentimiento/", get(consent_listar).post(consent_crear))
        .route(
            "/api/consentimiento/{id}",
            get(consent_detalle).put(consent_actualizar),
        )
        .route("/api/consentimiento/{id}/revocar", post(consent_revocar))
        .route("/api/incapacidades", get(incap_listar))
        .route("/api/incapacidades/resumen", get(incap_resumen))
        .route("/api/incapacidades/{historia_id}", get(incap_detalle))
        .route("/api/remisiones", get(rem_listar))
        .route("/api/remisiones/resumen", get(rem_resumen))
        .route("/api/remisiones/{id}", get(rem_obtener))
        .route("/api/remisiones/{id}/estado", put(rem_estado))
        .route("/api/contrarreferencia", get(cr_listar).post(cr_crear))
        .route("/api/contrarreferencia/remisiones-abiertas", get(cr_rem_abiertas))
        .route("/api/contrarreferencia/{id}", get(cr_obtener))
        .route("/api/contrarreferencia/{id}/recibir", post(cr_recibir))
        .route("/api/historias/{id}/formulas", get(listar_formulas).post(crear_formula))
        .route("/api/formulas/{id}", put(actualizar_formula).delete(eliminar_formula))
        .route("/api/historias/{id}/ordenes", get(listar_ordenes).post(crear_orden))
        .route("/api/ordenes/{id}/estado", put(cambiar_estado_orden))
        .route("/api/ordenes/{id}", axum::routing::delete(eliminar_orden))
        .route(
            "/api/historias/{id}/imagenes",
            get(listar_imagenes)
                .post(subir_imagen)
                // El tope alto vale SOLO para esta ruta: las demás siguen con el
                // límite modesto de axum, que basta para JSON.
                .layer(DefaultBodyLimit::max(MAX_SUBIDA)),
        )
        .route("/api/imagenes/{id}/archivo", get(servir_imagen))
        .route("/api/imagenes/{id}/previa", get(servir_previa))
        .route("/api/imagenes/{id}", axum::routing::delete(eliminar_imagen))
        // Laboratorio. Las órdenes las crea la historia clínica; aquí se
        // procesan. Leer es de cualquiera con sesión —el médico consulta el
        // resultado de su paciente—; escribir exige `EscribirLaboratorio`.
        .route("/api/laboratorio/ordenes", get(lab_ordenes))
        .route("/api/laboratorio/ordenes/{id}", get(lab_orden))
        .route("/api/laboratorio/ordenes/{id}/estado", put(lab_estado))
        .route(
            "/api/laboratorio/ordenes/{id}/resultado",
            get(lab_resultado).post(lab_crear_resultado).put(lab_actualizar_resultado),
        )
        .route("/api/laboratorio/ordenes/{id}/resultado/validar", post(lab_validar))
        .route("/api/laboratorio/paciente/{id}/resultados", get(lab_historial))
        .route("/api/laboratorio/perfiles", get(lab_perfiles).post(lab_crear_perfil))
        .route("/api/laboratorio/perfiles/{id}", axum::routing::delete(lab_eliminar_perfil))
        // Imágenes diagnósticas. Conviven con `/api/imagenes/{id}` y
        // `/api/imagenes/{id}/archivo`, que son los ADJUNTOS de la historia: los
        // segmentos literales (`ordenes`, `paciente`) tienen prioridad sobre el
        // parámetro, así que no se pisan. La prueba `las_rutas_de_imagenes_no_se_pisan`
        // lo comprueba en vez de confiarlo al enrutador.
        .route("/api/imagenes/ordenes", get(img_ordenes))
        .route("/api/imagenes/ordenes/{id}", get(img_orden))
        .route("/api/imagenes/ordenes/{id}/estado", put(img_estado))
        .route(
            "/api/imagenes/ordenes/{id}/informe",
            get(img_informe).post(img_crear_informe).put(img_actualizar_informe),
        )
        .route("/api/imagenes/ordenes/{id}/informe/firmar", post(img_firmar))
        .route(
            "/api/imagenes/ordenes/{id}/informe/imagenes",
            post(img_subir).layer(DefaultBodyLimit::max(MAX_SUBIDA)),
        )
        .route("/api/imagenes/paciente/{id}/informes", get(img_historial))
        .route("/api/instituciones", get(listar_instituciones).post(crear_institucion))
        .route("/api/instituciones/{id}/licencia", put(fijar_licencia))
        .route("/api/usuarios", get(listar_usuarios).post(crear_usuario))
        .route("/api/usuarios/{id}/documento", put(fijar_documento_usuario))
        // El RESCATE: retirarle el segundo factor a quien perdió el teléfono Y
        // sus códigos. Sin esto, esa persona se queda sin cuenta para siempre
        // —`retirar` exige estar dentro, y restablecerle la contraseña no ayuda
        // porque el segundo paso sigue en medio— y la única salida sería
        // `sqlite3` sobre la base de producción.
        .route("/api/usuarios/{id}/2fa", delete(retirar_2fa_de_otro))
        // El menú que ve cada institución (#65). Leerlo basta con estar
        // autenticado; cambiar la licencia es del vendedor, no del cliente.
        .route("/api/modulos", get(crate::modulos::listar))
        // El RIPS del periodo (#250). Solo emite el AC todavía, y se niega a
        // hacerlo sin que se lo pidan: ver la cabecera de `crate::rips`.
        .route("/api/rips", get(crate::rips::generar))
        // El documento ÚNICO del MUV, a partir de los mismos cinco. Es una
        // ruta aparte y no un parámetro de la de arriba porque el sobre pide
        // datos que la otra no tiene —`numNota` o la factura y su XML—, y
        // meterlos como opcionales dejaría dos formatos detrás de una firma.
        .route("/api/rips/fev", get(crate::rips::generar_fev))
        .route(
            "/api/instituciones/{id}/modulos",
            put(crate::modulos::fijar),
        )
        // La matriz de capacidades de la institución (#235). Misma capacidad
        // que gestionar usuarios: quién es quién y quién puede qué son la misma
        // responsabilidad.
        .route(
            "/api/capacidades",
            get(crate::capacidades::obtener).put(crate::capacidades::actualizar),
        )
        .route("/api/medicos", get(listar_medicos))
        .route("/api/citas", get(listar_citas).post(crear_cita))
        .route("/api/citas/{id}/estado", put(cambiar_estado_cita))
        // Agenda (#237). LEER es de cualquiera con sesión: quien agenda desde el
        // mostrador tiene que ver los turnos libres para poder darlos. ESCRIBIR
        // —definir las franjas de un profesional, bloquearle un rato— exige
        // `GestionarAgenda`: a un médico no se le cierra la consulta del jueves
        // sin que se entere.
        //
        // El orden importa: los segmentos literales (`medicos`, `turnos`,
        // `bloqueos`, `indicadores`) van ANTES que `/api/agenda/{id}`, y
        // `las_rutas_de_agenda_no_se_pisan` lo comprueba en vez de confiarlo.
        .route("/api/agenda/medicos", get(agenda_medicos))
        .route("/api/agenda/turnos", get(agenda_turnos))
        .route("/api/agenda/indicadores", get(agenda_indicadores))
        .route(
            "/api/agenda/bloqueos",
            get(agenda_listar_bloqueos).post(agenda_crear_bloqueo),
        )
        .route(
            "/api/agenda/bloqueos/{id}",
            axum::routing::delete(agenda_borrar_bloqueo),
        )
        .route("/api/agenda", get(agenda_listar).post(agenda_crear))
        .route(
            "/api/agenda/{id}",
            get(agenda_obtener)
                .put(agenda_actualizar)
                .delete(agenda_borrar),
        )
        .route("/api/agenda/{id}/bloques", post(agenda_anadir_bloque))
        .route(
            "/api/agenda/{id}/bloques/{bloque_id}",
            put(agenda_activar_bloque).delete(agenda_borrar_bloque),
        )
        // Administración. Ni un GET con `Autenticado` pelado: la política de
        // seguridad y el rastro de accesos no son el menú de nadie.
        .route(
            "/api/admin/institucion",
            get(adm_institucion).put(adm_actualizar_institucion),
        )
        .route(
            "/api/admin/configuracion",
            get(adm_configuracion).put(adm_actualizar_configuracion),
        )
        .route(
            "/api/admin/politica-seguridad",
            get(adm_politica).put(adm_actualizar_politica),
        )
        .route("/api/admin/campos-dinamicos", get(adm_campos).post(adm_crear_campo))
        .route(
            "/api/admin/campos-dinamicos/{id}",
            put(adm_actualizar_campo).delete(adm_borrar_campo),
        )
        .route(
            "/api/admin/especialidades",
            get(adm_especialidades).post(adm_crear_especialidad),
        )
        .route("/api/admin/especialidades/{id}", delete(adm_borrar_especialidad))
        .route("/api/admin/entidades", get(adm_entidades).post(adm_crear_entidad))
        .route(
            "/api/admin/entidades/{id}",
            put(adm_actualizar_entidad).delete(adm_borrar_entidad),
        )
        .route("/api/admin/auditoria", get(adm_auditoria))
        .route("/api/admin/usuarios", get(adm_usuarios).post(adm_crear_usuario))
        .route(
            "/api/admin/usuarios/{id}",
            put(adm_actualizar_usuario).delete(adm_borrar_usuario),
        )
        .route("/api/admin/usuarios/{id}/reset-password", post(adm_reset_password))
        .route("/api/admin/usuarios/{id}/desbloquear", post(adm_desbloquear))
        // Quirófano. El orden importa: `/medicos` y `/salas` son literales y van
        // ANTES que cualquier `{id}`; hoy no chocan porque la programación
        // cuelga de `/programaciones`, y así se queda.
        .route("/api/quirofano/salas", get(quir_salas))
        .route("/api/quirofano/medicos", get(quir_medicos))
        .route(
            "/api/quirofano/programaciones",
            get(quir_listar).post(quir_crear),
        )
        .route("/api/quirofano/programaciones/{id}", get(quir_obtener))
        .route("/api/quirofano/programaciones/{id}/checklist", put(quir_checklist))
        .route("/api/quirofano/programaciones/{id}/iniciar", put(quir_iniciar))
        .route("/api/quirofano/programaciones/{id}/completar", put(quir_completar))
        .route("/api/quirofano/programaciones/{id}/cancelar", put(quir_cancelar))
        .route("/api/quirofano/programaciones/{id}/suspender", put(quir_suspender))
        // Estadísticas. Ocho GET y ni un solo verbo de escritura: es un módulo
        // de lectura entero, y por eso ninguna de estas rutas aparece en la
        // lista de excepciones de `ninguna_escritura_se_conforma_con_estar_autenticado`.
        .route("/api/estadisticas/resumen", get(est_resumen))
        .route("/api/estadisticas/kpis", get(est_kpis))
        .route("/api/estadisticas/citas", get(est_citas))
        .route("/api/estadisticas/pacientes", get(est_pacientes))
        .route("/api/estadisticas/diagnosticos", get(est_diagnosticos))
        .route("/api/estadisticas/produccion", get(est_produccion))
        .route("/api/estadisticas/financiero", get(est_financiero))
        .route("/api/estadisticas/urgencias", get(est_urgencias))
        .route("/api/estadisticas/cobertura", get(est_cobertura))
        // Farmacia. Leer no exige capacidad; escribir sí (`GestionarFarmacia`).
        .route("/api/farmacia/stats", get(farm_stats))
        .route("/api/farmacia/inventario", get(farm_listar).post(farm_crear))
        .route(
            "/api/farmacia/inventario/{id}",
            put(farm_actualizar).delete(farm_eliminar),
        )
        .route("/api/farmacia/inventario/{id}/entrada", post(farm_entrada))
        .route("/api/farmacia/formulas-pendientes", get(farm_formulas_pendientes))
        .route("/api/farmacia/dispensar", post(farm_dispensar))
        .route("/api/farmacia/dispensaciones", get(farm_dispensaciones))
        .route("/api/farmacia/movimientos", get(farm_movimientos))
        .route(
            "/api/farmacia/proveedores",
            get(prov_listar).post(prov_crear),
        )
        .route(
            "/api/farmacia/proveedores/{id}",
            get(prov_obtener).put(prov_actualizar).delete(prov_eliminar),
        )
        // Ambulancias. `traslados` es un segmento literal y va antes que `{id}`,
        // como en `/api/imagenes`.
        .route("/api/ambulancias", get(amb_listar).post(amb_crear))
        .route("/api/ambulancias/traslados", get(amb_traslados).post(amb_despachar))
        .route("/api/ambulancias/traslados/{id}", get(amb_traslado))
        .route("/api/ambulancias/traslados/{id}/finalizar", post(amb_finalizar))
        .route("/api/ambulancias/traslados/{id}/cancelar", post(amb_cancelar))
        .route(
            "/api/ambulancias/{id}",
            get(amb_obtener).put(amb_actualizar).delete(amb_eliminar),
        )
        // Facturación. Los tres segmentos literales —`glosas`, `contratos` y
        // `entidades`— son hermanos de `facturas`, así que no compiten con
        // `{id}`; dentro de `facturas` sí hay que dejar `{id}` para el final.
        .route("/api/facturacion/stats", get(fac_stats))
        .route(
            "/api/facturacion/facturas",
            get(fac_listar).post(fac_crear),
        )
        .route(
            "/api/facturacion/facturas/{id}",
            get(fac_obtener).put(fac_actualizar).delete(fac_eliminar),
        )
        .route("/api/facturacion/facturas/{id}/radicar", put(fac_radicar))
        .route("/api/facturacion/facturas/{id}/estado", put(fac_estado))
        .route(
            "/api/facturacion/facturas/{id}/detalles",
            post(fac_detalle_agregar),
        )
        .route(
            "/api/facturacion/facturas/{id}/detalles/{detalle_id}",
            delete(fac_detalle_eliminar),
        )
        .route(
            "/api/facturacion/facturas/{id}/glosas",
            post(fac_glosa_agregar),
        )
        .route("/api/facturacion/glosas", get(fac_glosas))
        .route(
            "/api/facturacion/glosas/{id}/responder",
            put(fac_glosa_responder),
        )
        .route(
            "/api/facturacion/contratos",
            get(fac_contratos).post(fac_contrato_crear),
        )
        .route(
            "/api/facturacion/contratos/{id}",
            put(fac_contrato_actualizar),
        )
        .route("/api/facturacion/entidades", get(fac_entidades))
        // Catálogos de referencia: los lee cualquier usuario autenticado.
        .route("/api/especialidades", get(listar_especialidades))
        .route("/api/medicamentos/buscar", get(buscar_medicamentos))
        // El buscador de procedimientos (#331, prerrequisito): sin él no hay
        // forma de capturar el CUPS de la consulta, que hoy nadie captura.
        .route("/api/cups/buscar", get(buscar_cups))
        .route("/api/unidades-dispensacion", get(listar_unidades_dispensacion))
        // Las dos tablas de la 948 que la historia tiene que ofrecer para que
        // el médico ELIJA. Hasta el 2026-08-02 no se ofrecían y el sistema las
        // rellenaba solo, con códigos que además eran de la tabla anterior.
        .route("/api/finalidades", get(listar_finalidades))
        .route("/api/causas-motivo", get(listar_causas_motivo))
        .route(
            "/api/tipos-documento-profesional",
            get(listar_tipos_documento_profesional),
        )
        // EL PANEL EN `maud` (directiva 26). Se fusiona ANTES de la capa de
        // licencia, y eso no es un detalle: `route_layer` solo envuelve lo que
        // ya existe, así que un panel montado debajo se serviría sin licencia
        // —el mismo agujero que `la_capa_va_despues_de_la_ultima_ruta` vigila—.
        //
        // **Desde el 2026-08-08 el panel ES el producto**: Angular se retiró
        // entero y `/` redirige a `/panel`. Ver `vista::rutas`.
        .merge(crate::vista::rutas())
        // LA LICENCIA POR MÓDULO, EN EL SERVIDOR (#534). Va con `route_layer` y
        // no con `layer`, y la diferencia importa: `route_layer` NO envuelve el
        // `fallback`, así que la interfaz embebida y sus archivos se sirven
        // igual. Con `layer` habría que licenciar el `index.html`, o sea que a
        // un cliente al que le falte un módulo no le arrancaría la aplicación.
        //
        // ══ NO REGISTRES NINGUNA RUTA DEBAJO DE ESTA LÍNEA ══
        //
        // `route_layer` envuelve SOLO los endpoints que ya existían cuando se
        // aplica (axum 0.8, `path_router.rs`): una `.route(` escrita después
        // queda **sin licencia**, y el guardián de fuente no lo veía porque solo
        // preguntaba si la ruta estaba DECIDIDA, no si la capa llegaba a ella.
        //
        // No es hipotético: lo midió la revisión de seguridad de este mismo
        // cambio, y se reprodujo aquí — una ruta de NUTRICION puesta debajo
        // respondió **200** contra una institución que no lo compró, mientras la
        // de al lado respondía 403, y las 17 pruebas del guardián siguieron en
        // verde. Es exactamente el modo de fallo del que viene #534.
        //
        // Hoy lo impide `la_capa_va_despues_de_la_ultima_ruta`, que compara las
        // posiciones en el fuente de esta llamada y de la última `.route(` de
        // TODA la función —incluido lo que vaya tras el `.fallback(`—.
        .route_layer(axum::middleware::from_fn_with_state(
            estado.clone(),
            crate::licencia::exigir_modulo_licenciado,
        ))
        // **Lo que no case es un 404 de verdad**, y esa es la diferencia que
        // dejó el 2026-08-08. Antes aquí estaba el comodín del SPA
        // (`estaticos::servir`), que devolvía el `index.html` de Angular con
        // **200** a cualquier ruta desconocida: una errata en un `<script src>`
        // recibía HTML, el navegador lo descartaba por el MIME y la pantalla se
        // veía bien sin que nada fallara. Retirado Angular, el comodín no tiene
        // a quién servir y se queda el 404.
        //
        // El `.fallback(` se conserva **también como marca**: `modulos::sirve` y
        // el guardián de la licencia leen el router «desde `Router::new()` hasta
        // `.fallback(`», y quitarlo los haría entrar en pánico al arrancar.
        .fallback(no_encontrado)
        // Después de `fallback` y antes de `with_state`: así cubre TODAS las
        // respuestas, incluidas las de la interfaz y las de una ruta que no existe.
        .layer(axum::middleware::from_fn(cabeceras_de_seguridad))
        .with_state(estado)
}

/// Lo que no reconoce ninguna ruta. **404 en texto plano y sin pistas**: decir
/// qué prefijos existen convertiría el 404 en un inventario del producto para
/// cualquiera desde fuera, que es la misma razón por la que la capa de licencia
/// deja pasar a quien no tiene sesión.
async fn no_encontrado() -> Response {
    (StatusCode::NOT_FOUND, "no existe").into_response()
}

// `es_gestor` ya no existe. Comprobaba el rol A MANO —`Admin | Superadmin`— y
// por tanto NO consultaba la matriz de capacidades por institución (#235): una
// institución podía quitarle `gestionar_usuarios` a `admin`, la matriz lo
// aceptaba, la pantalla lo pintaba revocado… y `/api/usuarios` seguía dejándole
// entrar. Peor: la prueba `un_admin_no_se_quita_a_si_mismo_la_administracion`
// BENDICE ese estado, así que había una prueba en verde sobre una promesa que
// esa ruta no cumplía.
//
// Las dos rutas que lo usaban piden ahora `Autorizado<GestionarUsuarios>`, que
// es el único sitio donde esa pregunta se responde. Quitar la copia débil es el
// arreglo; dejarla y «acordarse» de sincronizarla, no (directiva 1).

#[derive(Serialize)]
struct Ok2 {
    ok: bool,
}

#[derive(Deserialize)]
pub struct Credenciales {
    pub email: String,
    pub clave: String,
}

/// De dónde viene la petición, para el freno de `/api/acceso`.
///
/// Detrás de nginx la dirección del zócalo es siempre `127.0.0.1`, así que hace
/// falta una cabecera. **Cuál, decide si el freno funciona.**
///
/// # Por qué `X-Real-IP` y no `X-Forwarded-For`
///
/// Esto leía el primer salto de `X-Forwarded-For`, razonando que con
/// `MEDICO_TRAS_PROXY` esa cabecera «la pone nuestro nginx y no el cliente». La
/// premisa era falsa. `frontend/nginx.conf` la escribe con
/// `$proxy_add_x_forwarded_for`, que **añade**, no sobrescribe: es
/// `$http_x_forwarded_for, $remote_addr`. Un cliente que mande
/// `X-Forwarded-For: 1.2.3.4` produce `1.2.3.4, <su IP real>`, y el primer salto
/// —el que se leía— es justo el valor que él eligió.
///
/// Es decir: en la única postura para la que se escribió (`tras_proxy` activo,
/// detrás de nuestro nginx), bastaba cambiar un número por petición para no
/// acumular ninguno. El control existía, estaba probado y documentado, y **no
/// frenaba**. La prueba que lo cubría pasaba porque simulaba el valor que pone el
/// proxy, no uno falsificado por el cliente.
///
/// `X-Real-IP` sí se escribe con `$remote_addr` (misma plantilla, línea de
/// arriba): es un valor, no una lista, y nginx **pisa** lo que traiga el cliente.
/// Es la misma elección que hace `informes` en su módulo `origen`.
///
/// # Y por qué ya no hay `desconocido`
///
/// Antes, si no había cabecera ni zócalo se devolvía `"desconocido"` y todos los
/// intentos compartían cubo. Eso no es «degradar con seguridad»: es el freno por
/// cuenta sola, que es la variante que este módulo rechazó al diseñarse porque
/// deja que un desconocido eche al dueño de la cuenta. Ante el dato ausente se
/// devuelve `None` y quien llama decide — y decide no dejar pasar.
fn origen_de(
    tras_proxy: bool,
    cabeceras: &header::HeaderMap,
    zocalo: Option<std::net::SocketAddr>,
) -> Option<String> {
    if tras_proxy {
        return cabeceras
            .get("x-real-ip")
            .and_then(|v| v.to_str().ok())
            .map(str::trim)
            .filter(|p| !p.is_empty())
            .map(str::to_owned);
    }
    // Sin proxy declarado, la dirección del zócalo: el cliente no la elige.
    zocalo.map(|s| s.ip().to_string())
}

/// Login. 200 con la cookie de sesión, 401 si no, **429 si se está probando**.
///
/// Un solo mensaje para todos los fallos: no se dice si el correo existe. El
/// freno se consulta ANTES de verificar la contraseña —si no, cada petición
/// frenada seguiría costando su Argon2 y el ensayo seguiría avanzando— y el
/// intento se anota SIEMPRE, acierte o falle, porque la cuenta de fallos se hace
/// desde el último acierto.
/// **El intento de entrar, sin forma.** La decide esta función y la visten sus
/// dos llamadores: `acceso` (JSON, `/api/acceso`) y el panel en `maud`
/// (`vista::entrada`).
///
/// Se extrajo al migrar el frontal al estándar nuevo (2026-08-06), y la razón es
/// la directiva 1: el panel necesita el MISMO comportamiento —el freno, el hash
/// de descarte, qué se le anota a quién, cuándo se responde 503— y copiarlo
/// habría creado una segunda copia que se queda atrás en el primer arreglo. Lo
/// único que cambia entre los dos es cómo se dibuja el final.
///
/// **Aquí no se decide nada nuevo**: el cuerpo es el que tenía `acceso` desde que
/// se escribió, con los finales devueltos en vez de renderizados.
pub async fn intentar_acceso(
    e: &Estado,
    cabeceras: &header::HeaderMap,
    extensiones: &axum::http::Extensions,
    cred: &Credenciales,
) -> Acceso {
    // Se lee de las extensiones y no con el extractor `ConnectInfo` porque este
    // último RECHAZA la petición cuando el servidor no se montó con
    // `with_connect_info` — y así lo montan las pruebas, que llaman al router sin
    // red. Un login que devuelve 500 en las pruebas por no tener zócalo sería un
    // freno que impide probar el freno.
    let zocalo = extensiones
        .get::<axum::extract::ConnectInfo<std::net::SocketAddr>>()
        .map(|c| c.0);
    let Some(origen) = origen_de(e.tras_proxy, cabeceras, zocalo) else {
        // Mismo criterio que un fallo al leer el freno: si no se puede aplicar,
        // no se deja pasar. Rellenarlo con un valor común pondría a todo el
        // mundo en el mismo cubo, y entonces cinco peticiones de un desconocido
        // dejan fuera a la doctora — el bloqueo que este freno existe para no
        // tener.
        eprintln!(
            "⚠️  no se pudo determinar el origen de la petición. Con MEDICO_TRAS_PROXY \
             activo hace falta que el proxy escriba X-Real-IP (proxy_set_header \
             X-Real-IP $remote_addr)."
        );
        return Acceso::NoSePudo;
    };
    let ahora = chrono::Utc::now();

    match medico_datos::freno::estado(&e.pool, &cred.email, &origen, ahora).await {
        Ok(f) if f.frenado() => {
            // EL INTENTO FRENADO NO SE ANOTA, y esto es lo contrario de lo que
            // hacía antes. La razón que lo justificaba —«si no, insistir durante
            // la espera saldría gratis»— suena bien y convierte el freno en lo
            // único que el diseño dice no ser: un bloqueo.
            //
            // Con el intento anotado, cada reintento durante la espera suma un
            // fallo, y como la espera dobla por fallo, quien insiste llega al
            // techo de cinco minutos y SE QUEDA ahí mientras siga insistiendo: en
            // cuanto vence, un clic lo devuelve arriba. Eso no le pasa a un
            // atacante paciente —él espera—, le pasa a la doctora que pulsa tres
            // veces porque cree que la página se colgó. El freno existe para
            // limitar el RITMO de ensayo, no para castigar la impaciencia, y
            // «nadie tiene que desbloquear a nadie» deja de ser cierto si la
            // víctima puede encerrarse sola.
            //
            // Insistir tampoco sale gratis: se responde 429 y la espera no se
            // acorta por pedirla más veces. Y hay una segunda razón, de la misma
            // familia que el corte del correo largo: anotar aquí es UNA ESCRITURA
            // EN LA BASE POR PETICIÓN NO AUTENTICADA. Justo lo que este camino
            // debe evitar.
            //
            // informes hace esto mismo (`rutas.rs`, rama `freno.frenado()`), y las
            // dos aplicaciones comparten la regla en `guaca::freno`. Diferir en
            // quién la alimenta hacía que la misma regla se comportara distinto.
            eprintln!("acceso frenado para «{}» desde {origen}", cred.email);
            return Acceso::Frenado(f.segundos_restantes());
        }
        Ok(_) => {}
        Err(err) => {
            // No se puede leer el freno: NO se deja pasar. Un fallo de la base en
            // el camino de autenticación que abriera la puerta sería el peor
            // defecto posible, y «degradar con gracia» aquí significa exactamente
            // eso. La historia clínica espera; la puerta abierta no se arregla.
            eprintln!("⚠️  no se pudo consultar el freno de acceso: {err}");
            return Acceso::NoSePudo;
        }
    }

    let quien = crate::auth::autenticar_usuario(&e.pool, &cred.email, &cred.clave).await;

    // LA CONTRASEÑA MAL SÍ SE ANOTA, siempre. El acierto se decide más abajo,
    // porque con segundo factor **acertar la contraseña no es entrar**.
    let Some(u) = quien else {
        let _ = medico_datos::freno::anotar(&e.pool, &cred.email, &origen, false, ahora).await;
        return Acceso::Credenciales;
    };

    // ¿Esta cuenta exige código? Si NO SE PUEDE SABER, no se deja pasar. Es el
    // mismo criterio que el fallo al leer el freno, y por la misma razón: una
    // base ilegible que abriera la puerta entera sería el peor defecto posible,
    // y aquí «degradar con gracia» significaría exactamente saltarse el segundo
    // factor de todo el mundo.
    match medico_datos::segundofactor::situacion(&e.pool, u.id).await {
        Ok(s) if s.exige_codigo() => {
            // **NO SE ANOTA NADA**, y esto es el arreglo del hallazgo del
            // 2026-08-12. El primer paso de un acceso con segundo factor no es
            // un desenlace: la contraseña era buena, así que no hay fallo que
            // contar, pero nadie ha entrado, así que tampoco hay acierto.
            //
            // La primera versión anotaba el acierto AQUÍ, razonando que «lo que
            // el freno cuenta es el ensayo de contraseñas». El razonamiento era
            // bonito y estaba mal, y lo destapó `el_segundo_paso_tambien_se_frena`
            // devolviendo 401 donde esperaba 429: como el freno cuenta desde el
            // último acierto, **el atacante limpiaba el contador con su propia
            // contraseña correcta** antes de cada intento de código. Compartir la
            // cuenta entre los dos pasos solo funciona si el primero no la
            // reinicia.
            //
            // Lo que se temía al anotarlo pronto —que quien tiene la contraseña
            // encierre al dueño fallando códigos— sigue siendo cierto y sigue
            // estando acotado: el freno es una ESPERA que se agota sola y topa
            // en cinco minutos, no un bloqueo. Cinco minutos de molestia contra
            // un segundo factor que se adivina en media hora no es un cambio
            // difícil.
            // El número del pendiente sale de la BASE y se incrementa al pedirlo:
            // con eso, cualquier pendiente anterior de esta cuenta deja de valer
            // y solo hay uno vivo a la vez.
            let Ok(v) = medico_datos::segundofactor::abrir_pendiente(&e.pool, u.id).await else {
                return Acceso::NoSePudo;
            };
            Acceso::SegundoPaso(sesion::emitir_pendiente(
                &e.secreto,
                u.id,
                u.token_version,
                v,
            ))
        }
        Ok(_) => {
            // Sin segundo factor, esto SÍ es entrar: se anota el acierto y con
            // él se borra la cuenta de fallos, como siempre.
            let _ = medico_datos::freno::anotar(&e.pool, &cred.email, &origen, true, ahora).await;
            Acceso::Entra(sesion::emitir(&e.secreto, u.id, u.token_version, e.minutos))
        }
        Err(err) => {
            eprintln!("⚠️  no se pudo consultar el segundo factor de {}: {err}", u.id);
            Acceso::NoSePudo
        }
    }
}

/// Cómo acabó un intento de entrar. Es un enum y no un `Option<String>` porque
/// los cuatro finales se responden distinto y **el panel los tiene que
/// distinguir igual que la API**: un 429 no es un 401, y un 503 no es culpa de
/// quien escribe la contraseña.
pub enum Acceso {
    /// Dentro. Lleva la cookie ya emitida.
    Entra(String),
    /// La contraseña era buena y la cuenta tiene segundo factor: falta el
    /// código. Lleva el token PENDIENTE, que no es una sesión y no puede llegar
    /// a serlo —va firmado en otro dominio (`sesion::DOMINIO_PENDIENTE`)—.
    ///
    /// Es una variante propia y no un `Entra` con una bandera: si fuera lo
    /// segundo, cualquier llamador que se olvidara de mirar la bandera dejaría
    /// entrar sin código, y el compilador no diría nada. Así, añadirla puso
    /// rojos los dos llamadores hasta que los dos la trataron.
    SegundoPaso(String),
    /// Credenciales incorrectas. El texto no distingue «no existe» de «clave
    /// mala», a propósito.
    Credenciales,
    /// El freno pide esperar estos segundos. `u64` porque es lo que devuelve
    /// `guaca::freno`, y convertirlo aquí sería inventarse un signo.
    Frenado(u64),
    /// No se pudo decidir: origen indeterminable o base ilegible. **No se deja
    /// pasar**, y no se le cobra al usuario.
    NoSePudo,
}

/// `POST /api/acceso` — la forma JSON. La decisión la toma `intentar_acceso`.
async fn acceso(
    State(e): State<Estado>,
    cabeceras: header::HeaderMap,
    extensiones: axum::http::Extensions,
    Json(cred): Json<Credenciales>,
) -> Response {
    match intentar_acceso(&e, &cabeceras, &extensiones, &cred).await {
        Acceso::Entra(cookie) => (
            StatusCode::OK,
            [(header::SET_COOKIE, sesion::cabecera_abrir(&cookie, e.minutos, e.tras_proxy))],
            Json(Ok2 { ok: true }),
        )
            .into_response(),
        // 202 y no 200, y la diferencia importa: un 200 aquí es «estás dentro»
        // para todo cliente escrito antes de que existiera el segundo factor.
        // «Aceptado, incompleto» es lo que de verdad pasó, y ningún cliente
        // viejo lo puede confundir con un éxito.
        Acceso::SegundoPaso(pendiente) => (
            StatusCode::ACCEPTED,
            [(
                header::SET_COOKIE,
                sesion::cabecera_pendiente_abrir(&pendiente, e.tras_proxy),
            )],
            Json(SegundoFactorPendiente { segundo_factor: true }),
        )
            .into_response(),
        Acceso::Credenciales => StatusCode::UNAUTHORIZED.into_response(),
        Acceso::Frenado(segundos) => (
            StatusCode::TOO_MANY_REQUESTS,
            [(header::RETRY_AFTER, segundos.to_string())],
        )
            .into_response(),
        Acceso::NoSePudo => StatusCode::SERVICE_UNAVAILABLE.into_response(),
    }
}

/// **El segundo paso, sin forma.** La decide esta función y la visten sus dos
/// llamadores, igual que [`intentar_acceso`]: `/api/2fa/verificar` y el panel.
///
/// # Qué se comprueba, y en qué orden
///
/// 1. Que haya un pendiente válido y sin caducar.
/// 2. Que lo que valía al emitirlo SIGA valiendo: la cuenta activa, la
///    `token_version` sin subir y el segundo factor todavía puesto. Entre los
///    dos pasos caben cinco minutos, y en cinco minutos un administrador puede
///    haber dado de baja a esa persona o revocado sus sesiones.
/// 3. El código: TOTP, o uno de recuperación si tiene esa FORMA.
///
/// # Lo que se le cobra a quien teclea, y lo que no
///
/// Un secreto que no se deja descifrar **no es culpa suya** y no cuenta como
/// fallo: es una avería del servidor, y tratarla como «código incorrecto» la
/// dejaría probando para siempre. Un código de recuperación mal tecleado SÍ
/// cuenta, porque ése sí se llegó a comprobar de verdad.
pub async fn verificar_segundo_paso(
    e: &Estado,
    cabeceras: &header::HeaderMap,
    extensiones: &axum::http::Extensions,
    tecleado: &str,
) -> SegundoPaso {
    use medico_datos::segundofactor as sf;

    let Some(cookie) = sesion::pendiente_de_cabeceras(cabeceras) else {
        return SegundoPaso::SinPendiente;
    };
    let Some(pendiente) = sesion::verificar_pendiente(&e.secreto, &cookie) else {
        return SegundoPaso::SinPendiente;
    };

    // Lo que valía hace cinco minutos puede no valer ahora. Se relee TODO.
    let Ok(Some(u)) = medico_datos::usuario::por_id(&e.pool, pendiente.sesion.usuario_id).await
    else {
        return SegundoPaso::SinPendiente;
    };
    if !u.activo || u.token_version != pendiente.sesion.token_version {
        return SegundoPaso::SinPendiente;
    }

    // **SE CONSUME AQUÍ, valga el código o no**, y antes de mirarlo. La firma
    // sola es un bearer reenviable: borrar la cookie con `Max-Age=0` lo obedece
    // un navegador y lo ignora cualquier cliente que hable HTTP, que reenvía el
    // mismo valor con otro código hasta que caduque. El «quemado» vivía en el
    // cliente, que es donde no puede vivir.
    //
    // Va antes de comprobar el código y no después: si solo se gastara al
    // fallar, acertar dejaría el token vivo. Y la carrera la resuelve la base
    // (`rows_affected`), igual que el contador del TOTP.
    match medico_datos::segundofactor::consumir_pendiente(&e.pool, u.id, pendiente.version).await {
        Ok(true) => {}
        Ok(false) => return SegundoPaso::SinPendiente,
        Err(_) => return SegundoPaso::NoSePudo,
    }

    // ── EL FRENO CUBRE LOS DOS PASOS ──────────────────────────────────────
    //
    // Sin esto, el segundo factor no protege contra el único atacante para el
    // que existe. El freno del PRIMER paso cuenta fallos desde el último
    // acierto, y quien ya tiene la contraseña acierta siempre: el contador nunca
    // sube, así que puede pedir tokens pendientes sin límite y gastar uno por
    // código adivinado. Con la tolerancia de ±1 ventana hay TRES códigos válidos
    // de un millón —unos 166 000 intentos esperados—, que sin freno y sin el
    // `limit_req` de nginx (que solo existe en el vhost de la demostración) son
    // menos de media hora.
    //
    // Lo encontró la revisión de seguridad del 2026-08-12 comparando con
    // informes, que SÍ frena los dos pasos y lo dice en la cabecera de su
    // módulo. Las dos aplicaciones acababan de compartir la REGLA en
    // `guaca::dosfactores` justamente para no diverger, y divergían en quién la
    // alimenta.
    //
    // Se usa la MISMA clave `(correo, origen)` que el primer paso, a propósito:
    // el ensayo de contraseñas y el de códigos son el mismo asalto a la misma
    // cuenta desde el mismo sitio, y contarlos aparte le daría al atacante dos
    // presupuestos donde debe haber uno.
    let zocalo = extensiones
        .get::<axum::extract::ConnectInfo<std::net::SocketAddr>>()
        .map(|c| c.0);
    let Some(origen) = origen_de(e.tras_proxy, cabeceras, zocalo) else {
        eprintln!("⚠️  segundo paso sin origen determinable: no se deja pasar");
        return SegundoPaso::NoSePudo;
    };
    let ahora = chrono::Utc::now();
    match medico_datos::freno::estado(&e.pool, &u.email, &origen, ahora).await {
        Ok(f) if f.frenado() => {
            eprintln!("segundo paso frenado para «{}» desde {origen}", u.email);
            return SegundoPaso::Frenado(f.segundos_restantes());
        }
        Ok(_) => {}
        Err(err) => {
            // No se puede leer el freno: NO se deja pasar. Mismo criterio que en
            // el primer paso — un fallo de la base que abriera la puerta sería
            // el peor defecto posible.
            eprintln!("⚠️  no se pudo consultar el freno del segundo paso: {err}");
            return SegundoPaso::NoSePudo;
        }
    }

    let Ok(g) = sf::guardado(&e.pool, u.id, e.clave_reposo.as_deref()).await else {
        return SegundoPaso::NoSePudo;
    };
    if !g.situacion.exige_codigo() {
        // Le quitaron el segundo factor entre los dos pasos. La contraseña ya se
        // comprobó, así que entra — negarle el paso la dejaría fuera por una
        // puerta que acaban de retirar.
        return SegundoPaso::Entra(sesion::emitir(&e.secreto, u.id, u.token_version, e.minutos));
    }

    // La decisión, y DESPUÉS la anotación. Se anota SIEMPRE —acierte o falle—
    // porque el freno cuenta desde el último acierto: sin esta llamada, el
    // `estado` de arriba consultaría un contador que nadie sube y el freno no
    // podría dispararse jamás. Es la mitad que convierte la consulta en una
    // puerta (directiva 30: un guardián que no puede decir que no se ve igual
    // que uno sano).
    let veredicto = decidir_segundo_paso(e, &u, &g, tecleado, ahora).await;

    // **`NoSePudo` NO se anota, y eso lo corrige la revisión independiente.**
    // Antes iba `matches!(veredicto, Entra(_))`, que convierte todo lo que no
    // sea entrar en un FALLO DEL USUARIO — incluida una avería del servidor: un
    // secreto que no se descifra, la base que no responde. Le subía el freno a
    // quien no había hecho nada mal, contradecía el docstring de aquí arriba y
    // **divergía de la regla que vive en `guaca::dosfactores`** («no se pudo
    // comprobar nada, así que no se cobra»), que es justo lo que la extracción a
    // guaca existe para impedir.
    //
    // No abre nada (directiva 30, comprobado antes de escribirlo): `NoSePudo` no
    // lo provoca lo que el cliente teclea, sino un estado del servidor o de la
    // cuenta. Y cuando ocurre, NINGÚN código llega a comprobarse — con el secreto
    // ilegible fallan todos por igual—, así que no hay ensayo que financiar.
    let acierto = match veredicto {
        SegundoPaso::Entra(_) => Some(true),
        SegundoPaso::Incorrecto => Some(false),
        // `SinPendiente` tampoco: aquí no se ha comprobado ningún código.
        SegundoPaso::Frenado(_) | SegundoPaso::NoSePudo | SegundoPaso::SinPendiente => None,
    };
    if let Some(acierto) = acierto {
        let _ = medico_datos::freno::anotar(&e.pool, &u.email, &origen, acierto, ahora).await;
    }
    veredicto
}

/// El código en sí, ya con la cuenta releída y el freno consultado.
///
/// Se parte de [`verificar_segundo_paso`] para que la anotación en el freno
/// ocurra en UN solo sitio: con los `return` repartidos por las ramas, cualquier
/// camino nuevo se olvidaría de anotar y el freno se quedaría ciego justo por
/// donde entrara el atacante.
async fn decidir_segundo_paso(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    g: &medico_datos::segundofactor::Guardado,
    tecleado: &str,
    ahora: chrono::DateTime<chrono::Utc>,
) -> SegundoPaso {
    use medico_datos::segundofactor as sf;

    // La FORMA decide qué se comprueba. Un código de recuperación se puede
    // comprobar aunque el secreto TOTP sea ilegible: vive en otra tabla y no
    // necesita el secreto para nada.
    if sf::parece_codigo_de_recuperacion(tecleado) {
        return match sf::gastar_codigo(&e.pool, u.id, tecleado, ahora).await {
            Ok(true) => {
                SegundoPaso::Entra(sesion::emitir(&e.secreto, u.id, u.token_version, e.minutos))
            }
            Ok(false) => SegundoPaso::Incorrecto,
            Err(_) => SegundoPaso::NoSePudo,
        };
    }

    let Some(secreto) = g.secreto.as_deref() else {
        eprintln!("⚠️  usuario {}: el secreto TOTP guardado no es legible", u.id);
        return SegundoPaso::NoSePudo;
    };

    let ahora_unix = ahora.timestamp().max(0) as u64;
    match sf::verificar(secreto, tecleado.trim(), ahora_unix, g.ultimo_contador.map(|c| c as u64)) {
        sf::Veredicto::Correcto { contador } => {
            // Quemar el contador es lo que DECIDE. Si otra petición se adelantó
            // con el mismo código, aquí sale `false` y no entra: la carrera la
            // resuelve la base, no el orden en que lleguen (ver
            // `segundofactor::quemar_contador`).
            match sf::quemar_contador(&e.pool, u.id, contador).await {
                Ok(true) => SegundoPaso::Entra(sesion::emitir(
                    &e.secreto,
                    u.id,
                    u.token_version,
                    e.minutos,
                )),
                Ok(false) => SegundoPaso::Incorrecto,
                Err(_) => SegundoPaso::NoSePudo,
            }
        }
        sf::Veredicto::Incorrecto | sf::Veredicto::Reutilizado => SegundoPaso::Incorrecto,
        sf::Veredicto::SecretoIlegible => {
            eprintln!("⚠️  usuario {}: el secreto TOTP no se pudo interpretar", u.id);
            SegundoPaso::NoSePudo
        }
    }
}

/// Cómo acabó el segundo paso. Cuatro finales, por lo mismo que [`Acceso`].
pub enum SegundoPaso {
    /// Dentro. Lleva la cookie de sesión de verdad.
    Entra(String),
    /// El código no vale —o se repitió—. **No se distingue cuál de las dos**:
    /// decirlo diría que el código ERA bueno, que es justo lo que quien repite
    /// quiere confirmar.
    Incorrecto,
    /// No hay pendiente, caducó, o lo que valía al emitirlo dejó de valer. Se
    /// manda a empezar de nuevo, sin decir cuál de las cosas falló.
    SinPendiente,
    /// El freno pide esperar estos segundos. Es la MISMA cuenta que la del
    /// primer paso: el ensayo de contraseñas y el de códigos son el mismo asalto.
    Frenado(u64),
    /// Avería del servidor. **No se le cobra a quien teclea.**
    NoSePudo,
}

/// `DELETE /api/usuarios/{id}/2fa` — el rescate, y **nunca sobre uno mismo**.
///
/// # Por qué está prohibido aplicárselo a sí mismo
///
/// Si valiera, sería la puerta de atrás de todo lo demás: una sesión de
/// administrador robada apagaría su propio segundo factor **sin saber ninguna
/// contraseña**, y con eso el factor no protegería precisamente a la cuenta que
/// más lo necesita. Para el suyo propio está `/panel/segundo-factor/retirar`,
/// que pide la contraseña.
///
/// Sale del hallazgo de la revisión de seguridad de informes, que encontró que
/// sin este endpoint quien perdía el teléfono Y los códigos se quedaba sin
/// cuenta para siempre.
async fn retirar_2fa_de_otro(
    State(e): State<Estado>,
    autorizado: Autorizado<GestionarUsuarios>,
    Path(id): Path<i64>,
) -> Response {
    let quien = autorizado.0;
    if quien.id == id {
        return StatusCode::FORBIDDEN.into_response();
    }

    // El aislamiento: un administrador no toca cuentas de otra institución. Se
    // comprueba con `es_del_ambito`, el mismo guardián que usan las otras rutas
    // de usuarios — y devuelve 404 y no 403, para no confirmar que ese id existe
    // en otra institución.
    match medico_datos::usuario::es_del_ambito(&e.pool, quien.ambito(), id).await {
        Ok(true) => {}
        Ok(false) => return StatusCode::NOT_FOUND.into_response(),
        Err(_) => return StatusCode::SERVICE_UNAVAILABLE.into_response(),
    }

    if medico_datos::segundofactor::desactivar(&e.pool, id).await.is_err() {
        return StatusCode::SERVICE_UNAVAILABLE.into_response();
    }

    // La línea en la bitácora. No lleva datos de paciente —es una acción sobre
    // una CUENTA—, así que va como colección SIN ids de titular, que es la forma
    // que `acceso::Objeto` reserva para lo que no cuelga de un paciente.
    registrar_coleccion(
        &e,
        &quien,
        "2fa_retirado_por_admin",
        &format!("usuario/{id}"),
        None,
        1,
        Vec::new(),
    )
    .await;

    StatusCode::NO_CONTENT.into_response()
}

#[derive(Deserialize)]
struct CodigoSegundoFactor {
    codigo: String,
}

/// `POST /api/2fa/verificar` — el segundo paso, en JSON.
async fn verificar_2fa(
    State(e): State<Estado>,
    cabeceras: header::HeaderMap,
    extensiones: axum::http::Extensions,
    Json(c): Json<CodigoSegundoFactor>,
) -> Response {
    match verificar_segundo_paso(&e, &cabeceras, &extensiones, &c.codigo).await {
        // `AppendHeaders` y NO un array de pares. Con el array, axum INSERTA:
        // dos `Set-Cookie` en la misma tupla y el segundo pisa al primero, así
        // que la respuesta salía solo con el borrado del pendiente y la sesión
        // se perdía por el camino — nadie con segundo factor habría podido
        // entrar. Lo cazó `el_codigo_correcto_abre_sesion_y_quema_el_pendiente`
        // antes de salir de aquí, y por eso esa prueba mira la cookie y no solo
        // el 200.
        SegundoPaso::Entra(cookie) => (
            StatusCode::OK,
            axum::response::AppendHeaders([
                (
                    header::SET_COOKIE,
                    sesion::cabecera_abrir(&cookie, e.minutos, e.tras_proxy),
                ),
                (
                    header::SET_COOKIE,
                    sesion::cabecera_pendiente_cerrar(e.tras_proxy),
                ),
            ]),
            Json(Ok2 { ok: true }),
        )
            .into_response(),
        // El pendiente se quema también al fallar: si sobreviviera, serviría
        // para seguir probando códigos con la contraseña ya dada por buena.
        SegundoPaso::Incorrecto => (
            StatusCode::UNAUTHORIZED,
            [(
                header::SET_COOKIE,
                sesion::cabecera_pendiente_cerrar(e.tras_proxy),
            )],
        )
            .into_response(),
        SegundoPaso::SinPendiente => StatusCode::UNAUTHORIZED.into_response(),
        // 429 y no 401: no es que el código esté mal, es que hay que esperar. Y
        // el pendiente NO se quema aquí — no se llegó a comprobar nada, así que
        // cobrarle el token a quien está esperando sería castigar la impaciencia.
        SegundoPaso::Frenado(segundos) => (
            StatusCode::TOO_MANY_REQUESTS,
            [(header::RETRY_AFTER, segundos.to_string())],
        )
            .into_response(),
        SegundoPaso::NoSePudo => StatusCode::SERVICE_UNAVAILABLE.into_response(),
    }
}

/// Lo que `/api/acceso` responde cuando falta el código. **No dice nada de la
/// cuenta** más allá de que hay segundo paso — que es un hecho que quien acaba
/// de acertar la contraseña ya conoce.
#[derive(Serialize)]
struct SegundoFactorPendiente {
    segundo_factor: bool,
}

#[derive(Deserialize)]
struct CambioPropio {
    actual: String,
    nueva: String,
}

/// `POST /api/mi-clave` — **la contraseña propia, para cualquier rol.**
///
/// Hasta el 2026-08-06 esto no existía, y ese hueco tenía dos consecuencias que
/// se tapaban entre sí: nadie podía cambiar su contraseña sin pedírselo a un
/// administrador, y por eso `requiere_cambio_password` —que el restablecimiento
/// SÍ escribe— era una bandera imposible de satisfacer. Marcar un deber que el
/// producto no deja cumplir es peor que no marcarlo.
///
/// Cuatro reglas, y ninguna es opcional:
///
/// 1. **Se exige la contraseña ACTUAL.** Sin ella, una sesión robada se queda
///    con la cuenta para siempre: el ladrón la cambia y el dueño ya no entra.
///    Se verifica con el mismo Argon2 del login.
/// 2. **La nueva pasa por la política de la institución**, la misma función que
///    el alta y el restablecimiento (`password_admisible`). Una tercera regla
///    aquí sería la puerta por la que entra la contraseña de un carácter.
/// 3. **Sube `token_version` en la MISMA sentencia**, que es lo que echa a quien
///    entró con la vieja. En dos sentencias habría un instante con la clave
///    nueva puesta y las sesiones viejas vivas.
/// 4. **Y se reemite la cookie**, porque la regla 3 también me expulsa a MÍ:
///    sin esto, cambiar la contraseña te echa de tu propia pantalla y nadie
///    vuelve a usar el botón.
///
/// La 3 y la 4 juntas son la diferencia entre «cerré todas las sesiones» y
/// «cerré todas menos la mía», que es lo que el usuario espera y lo que la
/// seguridad necesita.
/// El NÚCLEO de cambiar la propia contraseña, compartido por la API
/// (`mi_clave`) y la pantalla del panel (`/panel/cambiar-clave`, #538): las dos
/// reglas y su prueba viven en un solo sitio, no en dos copias que se separan.
/// Devuelve la COOKIE nueva —subir `token_version` echa a las sesiones viejas,
/// incluida la del que cambia, así que hay que reemitirle la suya (reglas 3 y 4
/// del doc de `mi_clave`)—; o `(código, motivo)` para que cada consumidor lo
/// dibuje a su manera.
pub(crate) async fn cambiar_clave_propia(
    e: &Estado,
    u: &usuario::Usuario,
    actual: &str,
    nueva: &str,
) -> Result<String, (StatusCode, String)> {
    if !claves::verificar(actual, &u.password_hash) {
        // 401 y no 403: lo que falla es probar quién eres, no un permiso. Y el
        // mensaje no distingue de un fallo de política, para no convertir esto
        // en un oráculo de contraseñas desde una sesión robada.
        return Err((StatusCode::UNAUTHORIZED, "la contraseña actual no coincide".into()));
    }
    let politica = match u.institucion_id {
        Some(inst) => administracion::politica(&e.pool, inst)
            .await
            .map_err(|_| (StatusCode::INTERNAL_SERVER_ERROR, "error de base de datos".into()))?,
        None => None,
    };
    if let Err(motivo) = administracion::password_admisible(nueva, politica.as_ref()) {
        return Err((StatusCode::BAD_REQUEST, motivo));
    }
    let Some(hash) = claves::hashear(nueva) else {
        return Err((StatusCode::INTERNAL_SERVER_ERROR, "no se pudo cifrar la contraseña".into()));
    };
    // Sube `token_version` y limpia `requiere_cambio_password` en la MISMA
    // sentencia: cerrar todas las sesiones y dar por cumplido el deber no pueden
    // quedar en dos pasos.
    match administracion::cambiar_password_propia(&e.pool, u.id, &hash).await {
        Ok(Some(version)) => Ok(sesion::emitir(&e.secreto, u.id, version, e.minutos)),
        Ok(None) => Err((StatusCode::NOT_FOUND, "usuario no encontrado".into())),
        Err(_) => Err((StatusCode::INTERNAL_SERVER_ERROR, "error de base de datos".into())),
    }
}

async fn mi_clave(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Json(p): Json<CambioPropio>,
) -> Response {
    match cambiar_clave_propia(&e, &u, &p.actual, &p.nueva).await {
        // La cookie NUEVA con la versión nueva: sigues dentro aquí y caes en el resto.
        Ok(cookie) => (
            StatusCode::OK,
            [(
                header::SET_COOKIE,
                sesion::cabecera_abrir(&cookie, e.minutos, e.tras_proxy),
            )],
            Json(Ok2 { ok: true }),
        )
            .into_response(),
        Err((codigo, motivo)) => (codigo, motivo).into_response(),
    }
}

/// Cierra la sesión borrando la cookie. No necesita estar autenticado: pedir
/// salir sin sesión no es un error.
///
/// Sí necesita el `Estado`, y solo por `tras_proxy`: la cookie de cierre lleva
/// los mismos atributos que la de apertura para que de verdad la sustituya.
async fn salir(State(e): State<Estado>) -> Response {
    (
        StatusCode::OK,
        [(header::SET_COOKIE, sesion::cabecera_cerrar(e.tras_proxy))],
        Json(Ok2 { ok: true }),
    )
        .into_response()
}

/// Cierra la sesión en TODOS los dispositivos (M3): sube el `token_version` del
/// usuario, con lo que toda cookie ya emitida —incluida la de este dispositivo—
/// deja de valer en la siguiente petición. Borra además la cookie de aquí. Actúa
/// sobre el usuario AUTENTICADO (nunca sobre un id que venga del cliente), así que
/// nadie revoca las sesiones de otro. Si la revocación falla, responde 500: no se
/// finge un cierre que no ocurrió (directiva de fallar en vez de suponer).
async fn salir_todo(State(e): State<Estado>, Autenticado(u): Autenticado) -> Response {
    match medico_datos::usuario::revocar_sesiones(&e.pool, u.id).await {
        Ok(true) => (
            StatusCode::OK,
            [(header::SET_COOKIE, sesion::cabecera_cerrar(e.tras_proxy))],
            Json(Ok2 { ok: true }),
        )
            .into_response(),
        // `false` = la sentencia no tocó ninguna fila: el usuario que acabamos de
        // autenticar ya no está. No hubo revocación, así que tampoco hay 200 —
        // descartar este booleano era justo fingir el cierre que el doc promete no fingir.
        Ok(false) => {
            eprintln!("⚠️  revocación sin efecto: el usuario {} ya no existe", u.id);
            StatusCode::INTERNAL_SERVER_ERROR.into_response()
        }
        Err(err) => {
            eprintln!("⚠️  no se pudieron revocar las sesiones de {}: {err}", u.id);
            StatusCode::INTERNAL_SERVER_ERROR.into_response()
        }
    }
}

#[derive(Serialize)]
struct Yo {
    id: i64,
    nombre: String,
    email: String,
    rol: Option<RolUsuario>,
    institucion_id: Option<i64>,
}

/// Quién soy. La interfaz la usa para restaurar la sesión y pintar el menú.
async fn yo(Autenticado(u): Autenticado) -> Json<Yo> {
    let rol = u.rol();
    Json(Yo {
        id: u.id,
        nombre: u.nombre,
        email: u.email,
        rol,
        institucion_id: u.institucion_id,
    })
}

#[derive(Serialize)]
struct CredencialesDemo {
    correo: String,
    clave: String,
}

/// Las credenciales de la DEMOSTRACIÓN, para que la pantalla de acceso las
/// muestre. **Sin sesión**, porque quien la necesita todavía no la tiene.
///
/// Responde `204 No Content` cuando el despliegue no pidió ser una demostración,
/// que es el defecto y lo que le pasa a la instalación de un cliente: no hay
/// nada que enseñar y no hay que acordarse de apagar nada. Publicar unas
/// credenciales exige poner DOS variables de entorno a propósito
/// (`MEDICO_DEMO_CORREO` y `MEDICO_DEMO_CLAVE`); media configuración no arranca.
///
/// No se registra en la bitácora de accesos: no hay titular ni dato de paciente
/// detrás, solo la nota de un cartel que el propio despliegue mandó colgar.
async fn demo(State(e): State<Estado>) -> Response {
    match &e.demo {
        Some(d) => Json(CredencialesDemo {
            correo: d.correo.clone(),
            clave: d.clave.clone(),
        })
        .into_response(),
        None => StatusCode::NO_CONTENT.into_response(),
    }
}

/// Pacientes, acotados al ámbito del usuario. El `ambito()` sale del rol y la
/// institución del usuario autenticado: nunca es un parámetro que el cliente
/// pueda mandar.
async fn listar_pacientes(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
) -> Result<Json<Vec<Paciente>>, StatusCode> {
    let lista = paciente::listar(&e.pool, u.ambito())
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    // El directorio de pacientes es dato personal: quién lo consultó y cuántos
    // vio va a la bitácora. Sin los ids —eso es lo que separa un listado de una
    // exportación—, y también cuando devuelve cero: «no hay pacientes» también
    // se consultó, y un rastro que solo anota lo que dio resultado deja fuera
    // justo el barrido de quien va probando.
    registrar_coleccion(&e, &u, "listar", RECURSO_PACIENTES, None, lista.len(), vec![]).await;
    Ok(Json(lista))
}

#[derive(Serialize)]
struct Creado {
    id: i64,
}

/// Un paciente por id, si es visible para el ámbito. **404 si no existe o no es
/// suyo** —nunca 403: un 403 confirmaría que el id existe en otra institución—.
async fn obtener_paciente(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Path(id): Path<i64>,
) -> Result<Json<Paciente>, StatusCode> {
    match paciente::obtener(&e.pool, u.ambito(), id).await {
        Ok(Some(p)) => {
            // La ficha del paciente ES el dato personal, y hasta el 2026-08-02
            // abrirla no dejaba rastro: se anotaba su historia y su documento,
            // pero no él. Un recurso único, que es lo que es.
            registrar_acceso(&e, &u, "ver", "paciente", id, id).await;
            Ok(Json(p))
        }
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

/// El rastro de acceso de un paciente (derecho del titular, Ley 1581). Restringido
/// al ámbito: un paciente ajeno no existe (404), igual que en el resto.
async fn accesos_paciente(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Path(id): Path<i64>,
) -> Result<Json<Vec<serde_json::Value>>, StatusCode> {
    match paciente::obtener(&e.pool, u.ambito(), id).await {
        Ok(Some(_)) => {}
        Ok(None) => return Err(StatusCode::NOT_FOUND),
        Err(_) => return Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
    // Los eventos vienen ya proyectados por la capa de datos: de una exportación
    // sale cuántos pacientes cubrió, nunca quiénes eran los otros.
    match acceso::por_paciente(&e.pool, u.ambito(), id).await {
        Ok(eventos) => Ok(Json(eventos)),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

/// Verifica la integridad de TODA la bitácora (encadenamiento + firmas). Solo
/// superadmin: es un control global, no de un recurso. Devuelve el veredicto.
async fn verificar_acceso(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
) -> Result<Json<serde_json::Value>, StatusCode> {
    if u.ambito() != Ambito::Superadmin {
        return Err(StatusCode::FORBIDDEN);
    }
    match acceso::verificar(&e.pool, e.clave_verificacion.as_deref()).await {
        Ok(veredicto) => Ok(Json(serde_json::json!({ "veredicto": format!("{veredicto:?}") }))),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

/// Crea un paciente en la institución del usuario. 201 con su id; 403 si el
/// ámbito no puede crear (superadmin sin institución, o sin ámbito).
/// Comprueba que el municipio, si viene, EXISTE en DIVIPOLA.
///
/// `None` es válido: un paciente puede no tener el dato todavía, y eso se ve.
/// Lo que no se acepta es un código inventado, que pasa la validación de
/// estructura del RIPS y sale mal en el envío, lejos de donde se tecleó. **Y no
/// se sustituye por ninguno**: el sistema viejo rellenaba con `"05001"` y
/// reportaba a todo el país como residente en Medellín — un dato falso no se
/// nota nunca, y eso es peor que un rechazo (directiva 20).
async fn municipio_valido(e: &Estado, cod: &Option<String>) -> Result<(), Response> {
    let Some(cod) = cod.as_deref() else { return Ok(()) };
    if cod.trim().is_empty() {
        return Ok(());
    }
    match medico_datos::divipola::existe(&e.pool, cod).await {
        Ok(true) => Ok(()),
        Ok(false) => Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            format!("el código de municipio «{cod}» no está en DIVIPOLA (van cinco dígitos, con el cero de la izquierda)"),
        )
            .into_response()),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR.into_response()),
    }
}

async fn crear_paciente(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirPaciente>,
    Json(nuevo): Json<PacienteNuevo>,
) -> Response {
    let u = autorizado.0;
    if let Err(r) = municipio_valido(&e, &nuevo.cod_municipio).await {
        return r;
    }
    match paciente::crear(&e.pool, u.ambito(), &nuevo).await {
        Ok(Some(id)) => (StatusCode::CREATED, Json(Creado { id })).into_response(),
        Ok(None) => StatusCode::FORBIDDEN.into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

/// `GET /api/municipios?q=…&limite=…` — el selector de la pantalla.
///
/// Solo pide estar autenticado: la lista de municipios de Colombia es pública y
/// no dice nada de ningún paciente. Exigirle una capacidad sería una regla que
/// no protege nada y que habría que recordar para cada pantalla nueva.
async fn listar_municipios(
    State(e): State<Estado>,
    _u: Autenticado,
    Query(q): Query<BuscarMunicipio>,
) -> Result<Json<Vec<medico_datos::divipola::Municipio>>, StatusCode> {
    // 20 por defecto: lo que cabe en un desplegable sin que haya que
    // desplazarse. El llamante puede pedir más; se acota a 500 para que un
    // parámetro suelto no arrastre el país entero por la red en cada tecla.
    let limite = q.limite.unwrap_or(20).clamp(1, 500);
    medico_datos::divipola::buscar(&e.pool, q.q.as_deref().unwrap_or(""), limite)
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

#[derive(serde::Deserialize)]
struct BuscarMunicipio {
    q: Option<String>,
    limite: Option<i64>,
}

/// Actualiza un paciente propio. 204 si se actualizó; **404 si no existe o no es
/// suyo** —nunca 403: un 403 confirmaría que el id existe en otra institución, y
/// eso ya enumera pacientes ajenos—.
async fn actualizar_paciente(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirPaciente>,
    Path(id): Path<i64>,
    Json(datos): Json<PacienteNuevo>,
) -> Response {
    let u = autorizado.0;
    // La misma comprobación que al crear. Sin esto, el municipio inválido entra
    // por la puerta de la edición: cerrar solo una de las dos deja el agujero
    // igual de abierto y encima parece cerrado.
    if let Err(r) = municipio_valido(&e, &datos.cod_municipio).await {
        return r;
    }
    match paciente::actualizar(&e.pool, u.ambito(), id, &datos).await {
        Ok(true) => StatusCode::NO_CONTENT.into_response(),
        Ok(false) => StatusCode::NOT_FOUND.into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

/// Actualiza los antecedentes (JSON) de un paciente propio. 204 si se actualizó;
/// **404 si no existe o no es suyo** —nunca 403, la misma regla que el resto—.
/// Solo se escriben los bloques presentes: guardar unos no borra los otros.
async fn actualizar_antecedentes_paciente(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirPaciente>,
    Path(id): Path<i64>,
    Json(ant): Json<Antecedentes>,
) -> StatusCode {
    let u = autorizado.0;
    match paciente::actualizar_antecedentes(&e.pool, u.ambito(), id, &ant).await {
        Ok(true) => StatusCode::NO_CONTENT,
        Ok(false) => StatusCode::NOT_FOUND,
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

// --- Historia clínica --------------------------------------------------------

/// El CUPS de una consulta tiene que existir **y reportarse en el AC**.
///
/// El buscador (`/api/cups/buscar?ambito=AC`) ya solo ofrece los del archivo de
/// consultas, pero eso es cortesía de pantalla: sin esta comprobación, el cuerpo
/// de la petición puede traer cualquier cadena y el filtro del buscador no
/// protege nada. Es la misma razón por la que `medico_id` se valida contra la
/// institución aunque el selector solo muestre los propios.
///
/// **Se rechaza con 422 y con el motivo escrito**, no en silencio: quien recibe
/// el error tiene que poder distinguir «ese código no existe» de «existe pero es
/// de procedimientos, no de consultas», que se corrigen de forma distinta.
///
/// `None` pasa: el campo sigue siendo opcional. Que la historia salga SIN CUPS
/// es una falta que el recolector anota en el cierre con su motivo — y eso es
/// mejor que un `890201` que nadie eligió, que es exactamente de donde venimos.
pub(crate) async fn cups_de_consulta_valido(e: &Estado, cups: Option<&str>) -> Result<(), Response> {
    let Some(c) = cups.map(str::trim).filter(|c| !c.is_empty()) else {
        return Ok(());
    };
    match catalogo::cups_es_de_ambito(&e.pool, c, catalogo::AmbitoRips::Ac).await {
        Ok(true) => Ok(()),
        Ok(false) => Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            format!(
                "el CUPS «{c}» no existe o no se reporta en el archivo de consultas \
                 (AC). Búsquelo con /api/cups/buscar?ambito=AC."
            ),
        )
            .into_response()),
        // No se puede comprobar: NO se deja pasar. Aceptarlo escribiría en la
        // historia un código que nadie validó, y el rechazo llegaría del MUV
        // semanas después sobre la factura del mes.
        Err(_) => Err(fallo_db()),
    }
}

async fn crear_historia(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirClinico>,
    Json(h): Json<HistoriaNueva>,
) -> Response {
    let u = autorizado.0;
    if let Err(r) = cups_de_consulta_valido(&e, h.cod_consulta_cups.as_deref()).await {
        return r;
    }
    // Quién registra sale de la SESIÓN. El cuerpo dice a quién se ATRIBUYE
    // (`medico_id`, ya validado contra la institución); quién teclea, no.
    match historia::crear(&e.pool, u.ambito(), u.id, &h).await {
        Ok(Some(id)) => (StatusCode::CREATED, Json(Creado { id })).into_response(),
        Ok(None) => StatusCode::FORBIDDEN.into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

// --- Los nombres de recurso de la bitácora, en UN sitio -----------------------
//
// Cada uno lo usan DOS llamantes: la ruta JSON y la pantalla del panel. Se
// escribían a mano en los dos —así entró imagenología— y eso deja la promesa
// «el panel anota con los MISMOS argumentos que su ruta» sostenida por que nadie
// se equivoque al teclear: una errata en uno de los dos parte el rastro de un
// mismo hecho en dos recursos distintos, y no da error en ninguna parte. Con la
// constante compartida, el mutante que la cambia mata la prueba de las DOS
// puertas a la vez, que es justo lo que se quiere.
//
// El singular es la ficha (`Recurso`) y el plural el listado (`Coleccion`), como
// en imagenología: `orden_imagenologia` / `ordenes_imagenologia`.
pub(crate) const RECURSO_PACIENTES: &str = "pacientes";
pub(crate) const RECURSO_ORDENES_IMAGEN: &str = "ordenes_imagenologia";
pub(crate) const RECURSO_ORDEN_IMAGEN: &str = "orden_imagenologia";
pub(crate) const RECURSO_INFORME_IMAGEN: &str = "informe_imagenologia";
pub(crate) const RECURSO_URGENCIAS: &str = "cola_urgencias";
/// El registro de nacimiento (#249). Nombre propio y no «recien_nacido» a
/// secas: lo que se lista lleva la identificación de la MADRE, y la bitácora
/// de la Ley 1581 se lee dentro de un año.
pub(crate) const RECURSO_RECIEN_NACIDOS: &str = "registro_nacimiento";
/// Los cuatro del bloque de enfermería. Recursos distintos y no uno solo: la
/// bitácora de la Ley 1581 se lee para responder «quién vio qué», y «vio el
/// kardex» y «vio la nota» son dos hechos distintos.
pub(crate) const RECURSO_NOTA_ENFERMERIA: &str = "nota_enfermeria";
pub(crate) const RECURSO_PLAN_CUIDADO: &str = "plan_cuidado";
pub(crate) const RECURSO_MAR: &str = "administracion_medicamento";
pub(crate) const RECURSO_KARDEX: &str = "kardex";
/// La preparación y el aval del RDA de un encuentro (#603 F4.5-C). Recurso propio:
/// «quién avaló el `nilknown` de esta historia» es una pregunta con peso legal
/// (afirma «sin hallazgos» ante el visor nacional), distinta de «quién vio la
/// historia».
pub(crate) const RECURSO_AVAL_RDA: &str = "aval_rda";
/// El certificado de defunción. Recurso propio: «quién consultó las defunciones»
/// es una pregunta que se hace, y no es la misma que «quién vio a este paciente».
pub(crate) const RECURSO_DEFUNCIONES: &str = "certificado_defuncion";
/// El censo diario. Lleva quién está en cada cama, así que deja eslabón.
pub(crate) const RECURSO_CENSO: &str = "censo_diario";
pub(crate) const RECURSO_PREANESTESIA: &str = "valoracion_preanestesica";
pub(crate) const RECURSO_RECUPERACION: &str = "recuperacion_postanestesica";
/// P&P. Un solo recurso para los cuatro programas, con el programa como filtro:
/// la bitácora guarda CUÁL se miró en el alcance, que es más informativo que
/// cuatro recursos distintos con el mismo hecho detrás.
pub(crate) const RECURSO_PYP: &str = "promocion_y_prevencion";
/// Habilitación. Lo de equipos y comités no es dato personal; lo de infecciones
/// SÍ —lleva paciente—, y por eso el recurso deja eslabón igual que los demás.
pub(crate) const RECURSO_HABILITACION: &str = "habilitacion";
pub(crate) const RECURSO_TRABAJO_SOCIAL: &str = "nota_trabajo_social";
pub(crate) const RECURSO_TELECONSULTA: &str = "teleconsulta";
// TURNOS no tiene recurso de bitácora, y es deliberado: un turno es la planta de
// personal, no dato de paciente. La Ley 1581 ata eslabones al TITULAR de un dato
// personal de salud, y aquí no hay ninguno. Se escribe para que la ausencia se
// lea como una decisión y no como un olvido.
/// El banco de sangre. Deja eslabón porque una transfusión es dato clínico del
/// paciente, no solo inventario.
pub(crate) const RECURSO_BANCO_SANGRE: &str = "banco_sangre";
pub(crate) const RECURSO_HOSPITALIZACIONES: &str = "hospitalizaciones";
pub(crate) const RECURSO_INCAPACIDADES: &str = "incapacidades";
pub(crate) const RECURSO_INCAPACIDAD: &str = "incapacidad";
pub(crate) const RECURSO_REMISIONES: &str = "remisiones";
pub(crate) const RECURSO_REMISION: &str = "remision";
pub(crate) const RECURSO_CITAS: &str = "citas";

/// El `filtro` de un eslabón de colección, a partir de los parámetros que la
/// petición traía de verdad.
///
/// Devuelve `None` cuando no venía ninguno —«se miró TODO», que es un hecho
/// distinto de «se miró con un filtro vacío»— y si no, los que vinieron, en el
/// orden en que se le pasan y sin los que faltan. Un `filtro` con
/// `estado=&buscar=` diría que hubo criterios que nadie escribió (directiva 20).
///
/// **Sí guarda el texto de la búsqueda, y es deliberado.** Ese texto suele ser
/// el nombre o el documento de un paciente, y esconderlo dejaría el eslabón en
/// «alguien listó incapacidades», que no sirve para auditar nada: lo que hace
/// falta saber es a quién fue a buscar. La bitácora es tratamiento legítimo y
/// vive acotada a la institución; una colección no entra en el rastro de ningún
/// titular (no lleva ids), así que ese texto no sale por ahí.
pub(crate) fn filtro_de(pares: &[(&str, Option<&str>)]) -> Option<String> {
    let puestos: Vec<String> = pares
        .iter()
        .filter_map(|(k, v)| {
            let v = v.map(str::trim).filter(|s| !s.is_empty())?;
            Some(format!("{k}={v}"))
        })
        .collect();
    (!puestos.is_empty()).then(|| puestos.join("; "))
}

/// Registra un acceso a dato de paciente en la bitácora (Ley 1581), **best-effort**:
/// si el registro falla NO se bloquea la atención — se grita en el log. El registro
/// es casi infalible (BEGIN IMMEDIATE + reintentos); un fallo es raro y queda
/// avisado. Decisión de Juan 2026-07-29: la seguridad del paciente por encima de la
/// formalidad del rastro.
pub(crate) async fn registrar_acceso(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    accion: &str,
    recurso: &str,
    recurso_id: i64,
    paciente_id: i64,
) {
    let evento = acceso::Evento {
        usuario_id: u.id,
        rol: u.rol.clone(),
        institucion_id: u.institucion_id,
        accion: accion.to_string(),
        recurso: recurso.to_string(),
        objeto: acceso::Objeto::Recurso {
            paciente_id,
            recurso_id,
        },
        ts: chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
    };
    if let Err(err) = acceso::registrar(&e.pool, &evento, e.clave_firma.as_deref()).await {
        eprintln!("⚠️  bitácora de acceso: no se registró {recurso} {recurso_id} (paciente {paciente_id}): {err}");
    }
}

/// El registro de un acceso a un CONJUNTO, best-effort como [`registrar_acceso`].
/// No se llama directamente: entra por [`registrar_coleccion`] o por
/// [`registrar_coleccion_de_un_titular`], que son las que eligen la forma.
async fn registrar_conjunto(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    accion: &str,
    recurso: &str,
    objeto: acceso::Objeto,
) {
    let evento = acceso::Evento {
        usuario_id: u.id,
        rol: u.rol.clone(),
        institucion_id: u.institucion_id,
        accion: accion.to_string(),
        recurso: recurso.to_string(),
        objeto,
        ts: chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
    };
    if let Err(err) = acceso::registrar(&e.pool, &evento, e.clave_firma.as_deref()).await {
        eprintln!("⚠️  bitácora de acceso: no se registró {accion} de {recurso}: {err}");
    }
}

/// Anota un **acto administrativo** en la bitácora encadenada: crear personal,
/// cambiarle el rol, restablecerle la contraseña, darlo de baja, quitarle el
/// freno o reescribir la política de seguridad.
///
/// **Antes de aplicar y de forma OBLIGATORIA**, al revés que el acceso a dato de
/// paciente, que es best-effort porque allí manda la atención. Es la misma
/// decisión —y el mismo texto— que `capacidades::registrar_cambio` ya había
/// tomado para la matriz: aquí no hay paciente esperando, y un acto que reparte
/// o revoca poder sobre datos clínicos sin rastro es justo lo que la bitácora
/// existe para impedir. Si no se puede registrar, no se aplica.
///
/// Existe porque **no existía**: medido sobre esta misma rama, las 24 rutas
/// `/api/admin/*` no llamaban a `acceso::registrar` ni una vez, mientras
/// `PUT /api/capacidades` sí lo hacía en la MISMA tabla y `adm_auditoria` la
/// sirve como la pantalla de auditoría de la institución. O sea que esa pantalla
/// no podía enseñar jamás quién le cambió los permisos a quién, ni quién
/// restableció la contraseña de un médico que firma historia clínica.
///
/// Va como `Coleccion` y no como `Recurso` por la razón de siempre: no hay UN
/// paciente. `alcance.pacientes` queda vacío —no salió dato de nadie— y el
/// `filtro` lleva el detalle, para que el eslabón diga QUÉ se hizo y no solo que
/// algo se tocó.
///
/// Los LISTADOS de administración no pasan por aquí, y es deliberado: los pide
/// cada pintado de pantalla, y una bitácora que crece con cada carga ahoga la
/// señal que existe para dar.
pub(crate) async fn anotar_acto_admin(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    accion: &str,
    recurso: &str,
    detalle: String,
) -> Result<(), Response> {
    let evento = acceso::Evento {
        usuario_id: u.id,
        rol: u.rol.clone(),
        institucion_id: u.institucion_id,
        accion: accion.to_string(),
        recurso: recurso.to_string(),
        objeto: acceso::Objeto::Coleccion {
            alcance: acceso::Alcance {
                ambito: acceso::describir_ambito(u.ambito()),
                filtro: Some(detalle),
                n: 1,
                pacientes: vec![],
            },
        },
        ts: chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
    };
    acceso::registrar(&e.pool, &evento, e.clave_firma.as_deref())
        .await
        .map_err(|_| {
            (
                StatusCode::SERVICE_UNAVAILABLE,
                "no se pudo registrar el acto en la bitácora: no se aplicó",
            )
                .into_response()
        })
}

/// El alcance de un conjunto visto por `u`. El ámbito sale del usuario, nunca de
/// un parámetro: es la misma regla que el RIPS aprendió a la mala.
fn alcance_visto_por(
    u: &medico_datos::usuario::Usuario,
    filtro: Option<String>,
    n: usize,
    pacientes: Vec<i64>,
) -> acceso::Alcance {
    acceso::Alcance {
        ambito: acceso::describir_ambito(u.ambito()),
        filtro,
        n: n as i64,
        pacientes,
    }
}

/// Un conjunto que **atraviesa titulares**: el directorio de pacientes, una
/// exportación de RIPS.
///
/// La diferencia con un recurso único no es cosmética (ver `acceso::Alcance`):
/// un **listado** anota a qué ámbito se consultó, con qué filtro y cuántos
/// salieron, y **no guarda ids** —ver un nombre en una lista no es abrir el
/// expediente, y un eslabón por fila ahogaría la cadena—; una **exportación**
/// sí guarda los pacientes que sacó, porque el dato salió del sistema y el
/// titular tiene derecho a saber que el suyo iba dentro (Ley 1581).
pub(crate) async fn registrar_coleccion(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    accion: &str,
    recurso: &str,
    filtro: Option<String>,
    n: usize,
    pacientes: Vec<i64>,
) {
    let alcance = alcance_visto_por(u, filtro, n, pacientes);
    registrar_conjunto(e, u, accion, recurso, acceso::Objeto::Coleccion { alcance }).await;
}

/// Un conjunto de registros de **UN titular**: sus historias, sus documentos,
/// sus resultados de laboratorio.
///
/// No lleva `pacientes` y no es negociable: esa lista significa «el dato salió
/// del sistema», y aquí no salió — el titular ya va nombrado aparte, que es lo
/// que hace que el acceso aparezca en SU rastro. En el rastro se lee
/// `pacientes_n: 0`, y esa es justo la diferencia que él necesita ver entre
/// alguien que consultó su expediente y alguien que se lo llevó.
pub(crate) async fn registrar_coleccion_de_un_titular(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    accion: &str,
    recurso: &str,
    paciente_id: i64,
    filtro: Option<String>,
    n: usize,
) {
    // EL TITULAR TIENE QUE SER DEL ÁMBITO DE QUIEN PREGUNTA, y se comprueba aquí
    // y no en cada ruta por lo mismo que `obtener()` existe en vez de arreglar
    // cada `db.get`: un control que hay que acordarse de poner en cuatro sitios
    // se olvida en el quinto.
    //
    // Sin esto, el `paciente_id` entraba tal cual de la petición. Las consultas
    // SÍ están aisladas —devuelven la lista vacía para un paciente ajeno, así que
    // no sale ni un dato—, pero el evento se sellaba igual: bastaba recorrer
    // identificadores contra `/api/pacientes/{id}/historias` para meter eslabones
    // firmados en el rastro de los pacientes de OTRA institución, donde su
    // titular los lee como accesos que nunca ocurrieron. Y no se pueden quitar:
    // la cadena está encadenada por hash, así que borrar el eslabón falso deja la
    // bitácora entera en `Rota`.
    //
    // Es la misma regla que ya seguían `obtener_paciente` y `contexto_paciente`,
    // que registran dentro del `Ok(Some(...))` — y que una ficha ajena no deje
    // rastro es justo lo que aquellas prueban.
    match acceso::paciente_es_del_ambito(&e.pool, u.ambito(), paciente_id).await {
        Ok(true) => {}
        // No es suyo: no hubo acceso a ese titular, así que no hay nada que anotar.
        Ok(false) => return,
        // Si no se puede saber, no se sella. Un eslabón que quizá sea falso vale
        // menos que ninguno: el rastro se lee para responder «¿quién miró mi
        // historia?», y ahí una duda sellada es una respuesta equivocada.
        Err(err) => {
            eprintln!(
                "⚠️  bitácora de acceso: no se registró {accion} de {recurso} (paciente {paciente_id}): no se pudo comprobar el ámbito: {err}"
            );
            return;
        }
    }
    let alcance = alcance_visto_por(u, filtro, n, vec![]);
    registrar_conjunto(
        e,
        u,
        accion,
        recurso,
        acceso::Objeto::DeUnTitular {
            paciente_id,
            alcance,
        },
    )
    .await;
}

async fn obtener_historia(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Path(id): Path<i64>,
) -> Result<Json<Historia>, StatusCode> {
    match historia::obtener(&e.pool, u.ambito(), id).await {
        Ok(Some(h)) => {
            registrar_acceso(&e, &u, "ver", "historia", id, h.paciente_id).await;
            Ok(Json(h))
        }
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

/// Edita una historia de borrador. 200 con la historia ya actualizada; **404 si
/// no existe o es ajena; 409 si está firmada** —cerrada, no editable—.
async fn actualizar_historia(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirClinico>,
    Path(id): Path<i64>,
    Json(h): Json<HistoriaNueva>,
) -> Response {
    let u = autorizado.0;
    // La MISMA puerta que al crear. Sin esto, el código inválido entraría por la
    // edición — que es el camino que más se usa, porque la historia se abre y se
    // completa varias veces durante la atención.
    if let Err(r) = cups_de_consulta_valido(&e, h.cod_consulta_cups.as_deref()).await {
        return r;
    }
    match historia::actualizar(&e.pool, u.ambito(), id, &h).await {
        Ok(historia::Resultado::Hecho) => match historia::obtener(&e.pool, u.ambito(), id).await {
            Ok(Some(actualizada)) => (StatusCode::OK, Json(actualizada)).into_response(),
            _ => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
        },
        Ok(historia::Resultado::NoExiste) => StatusCode::NOT_FOUND.into_response(),
        Ok(historia::Resultado::Firmada) => StatusCode::CONFLICT.into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

/// Firma una historia, que queda cerrada. 204 si se firmó; 404 si no existe, es
/// ajena o ya estaba firmada; **422 si le falta contenido clínico**, diciendo qué.
async fn firmar_historia(
    State(e): State<Estado>,
    // `Autorizado<Firmar>`: la firma afirma autoría clínica, así que la exige la
    // FIRMA del manejador y no un `if` que la próxima ruta olvidará.
    autorizado: Autorizado<Firmar>,
    Path(id): Path<i64>,
) -> Response {
    let u = autorizado.0;
    match historia::firmar(&e.pool, u.ambito(), id, u.id, e.clave_firma.as_deref()).await {
        Ok(historia::ResultadoFirma::Firmada) => StatusCode::NO_CONTENT.into_response(),
        Ok(historia::ResultadoFirma::NoSePudo) => StatusCode::NOT_FOUND.into_response(),
        // **422 y no 409**, igual que el informe radiológico: lo que falla no es
        // un conflicto de estado sino el CONTENIDO, y se dice cuál falta — «no se
        // pudo firmar» a secas manda a ir campo por campo adivinando.
        Ok(historia::ResultadoFirma::Incompleto { faltan }) => detalle(
            StatusCode::UNPROCESSABLE_ENTITY,
            format!(
                "No se puede firmar una historia a la que le falta {}. Una historia firmada \
                 acredita autoría y queda cerrada —para corregirla hay que emitir otra—: en \
                 blanco sería un documento que no dice nada, firmado.",
                faltan.join(", ")
            ),
        ),
        // Hay clave configurada y no sirve: es un fallo del DESPLIEGUE, no de la
        // petición, y no se disfraza de 404. Antes esto marcaba la historia como
        // firmada con `firma = NULL` y devolvía 204: una historia que afirmaba
        // estar firmada sin estarlo.
        Ok(historia::ResultadoFirma::ClaveInservible) => {
            eprintln!("⚠️  MEDICO_SIGNING_KEY no sirve: la historia {id} NO se firmó");
            StatusCode::INTERNAL_SERVER_ERROR.into_response()
        }
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

#[derive(Serialize)]
struct EstadoFirma {
    estado: &'static str,
}

/// Verifica la firma criptográfica de una historia contra su contenido actual.
/// `valida` / `alterada` / `invalida` / `sin_firma` (cerrada sin clave) /
/// `sin_clave` (el servidor no tiene clave pública configurada). 404 si la
/// historia no existe o no es del ámbito.
async fn verificar_firma_historia(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Path(id): Path<i64>,
) -> Response {
    let Some(vk) = e.clave_verificacion.as_deref() else {
        return (StatusCode::OK, Json(EstadoFirma { estado: "sin_clave" })).into_response();
    };
    match historia::verificar(&e.pool, u.ambito(), id, vk).await {
        Ok(Some(v)) => {
            let estado = match v {
                guaca::firma::Verificacion::Valida => "valida",
                guaca::firma::Verificacion::Alterada => "alterada",
                guaca::firma::Verificacion::Invalida => "invalida",
            };
            (StatusCode::OK, Json(EstadoFirma { estado })).into_response()
        }
        // La historia existe (se pudo consultar) pero no tiene firma, o no existe.
        Ok(None) => match historia::obtener(&e.pool, u.ambito(), id).await {
            Ok(Some(_)) => (StatusCode::OK, Json(EstadoFirma { estado: "sin_firma" })).into_response(),
            Ok(None) => StatusCode::NOT_FOUND.into_response(),
            Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
        },
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

/// Borra una historia de borrador. 204 si se borró; **404 si no existe o es
/// ajena; 409 si está firmada** —un documento legal cerrado no se elimina—.
async fn eliminar_historia(
    State(e): State<Estado>,
    autorizado: Autorizado<Borrar>,
    Path(id): Path<i64>,
) -> StatusCode {
    let u = autorizado.0;
    match historia::eliminar(&e.pool, u.ambito(), id).await {
        Ok(historia::Resultado::Hecho) => StatusCode::NO_CONTENT,
        Ok(historia::Resultado::NoExiste) => StatusCode::NOT_FOUND,
        Ok(historia::Resultado::Firmada) => StatusCode::CONFLICT,
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

/// El contexto del paciente para el encabezado del formulario: sus datos ya
/// compuestos y el médico que atiende (el usuario autenticado). **404 si el
/// paciente no existe o no es del ámbito**.
async fn contexto_paciente(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Path(paciente_id): Path<i64>,
) -> Result<Json<Contexto>, StatusCode> {
    match paciente::info(&e.pool, u.ambito(), paciente_id).await {
        Ok(Some(paciente)) => {
            registrar_acceso(&e, &u, "ver", "paciente", paciente_id, paciente_id).await;
            Ok(Json(Contexto {
            paciente,
            medico: InfoMedico {
                id: u.id,
                nombre_completo: u.nombre.clone(),
                // La especialidad y el registro médico del profesional aún no
                // viven en `usuario` (llegan con el maestro de talento humano);
                // hasta entonces, ausentes y no inventados.
                especialidad: None,
                registro_medico: None,
            },
            }))
        }
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

#[derive(Serialize)]
struct Contexto {
    paciente: InfoPaciente,
    medico: InfoMedico,
}

#[derive(Serialize)]
struct InfoMedico {
    id: i64,
    nombre_completo: String,
    especialidad: Option<String>,
    registro_medico: Option<String>,
}

async fn listar_historias_paciente(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Path(paciente_id): Path<i64>,
) -> Result<Json<Vec<Historia>>, StatusCode> {
    let hs = historia::listar_por_paciente(&e.pool, u.ambito(), paciente_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    registrar_coleccion_de_un_titular(&e, &u, "listar", "historias", paciente_id, None, hs.len())
        .await;
    Ok(Json(hs))
}

// --- Documentos clínicos (evolución, epicrisis, interconsulta, …) ------------

#[derive(Deserialize)]
struct FiltroDocumentos {
    paciente_id: Option<i64>,
    tipo: Option<String>,
}

/// La worklist de documentos visibles para el ámbito, con los nombres unidos.
/// Ambos filtros son opcionales: por tipo (una worklist de evoluciones) y por
/// paciente (los documentos de un paciente). Devuelve la vista ligera, sin
/// `contenido`; el editor pide el documento completo con `GET /{id}`.
async fn listar_documentos(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Query(f): Query<FiltroDocumentos>,
) -> Result<Json<Vec<DocumentoVista>>, StatusCode> {
    let ds = documento::listar_ambito(&e.pool, u.ambito(), f.paciente_id, f.tipo.as_deref())
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    // El mismo endpoint cae en DOS formas según lo que se pida, y es la regla la
    // que decide, no el caso: con `paciente_id` es el expediente de un titular y
    // entra en SU rastro; sin él atraviesa titulares y es una colección.
    let filtro = f.tipo.as_ref().map(|t| format!("tipo={t}"));
    match f.paciente_id {
        Some(p) => {
            registrar_coleccion_de_un_titular(&e, &u, "listar", "documentos", p, filtro, ds.len())
                .await
        }
        None => registrar_coleccion(&e, &u, "listar", "documentos", filtro, ds.len(), vec![]).await,
    }
    Ok(Json(ds))
}

/// Crea un documento. El autor es el usuario autenticado —no un campo del
/// cliente—. 201 con su id; 403 si el paciente no es del ámbito.
async fn crear_documento(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirClinico>,
    Json(d): Json<DocumentoNuevo>,
) -> Response {
    let u = autorizado.0;
    // Los tipos de enfermería NO entran por aquí, y no es un capricho de
    // organización: esta ruta exige `EscribirClinico` (médico) y acepta el
    // `tipo` que le manden. Si la nota de enfermería se pudiera crear desde
    // aquí, el registro diría que enfermería escribió algo que escribió un
    // médico — y la autoría es lo que hace válida la historia clínica. Su
    // puerta es `/api/enfermeria/*`, donde el tipo lo pone el servidor.
    if medico_datos::enfermeria::TIPOS_PROPIOS.contains(&d.tipo.as_str()) {
        return (
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "detail": format!(
                    "«{}» se crea por /api/enfermeria, no por aquí: su autoría es de \
                     enfermería y esta ruta la firma quien tenga EscribirClinico.",
                    d.tipo
                )
            })),
        )
            .into_response();
    }
    match documento::crear(&e.pool, u.ambito(), u.id, &d).await {
        Ok(Some(id)) => (StatusCode::CREATED, Json(Creado { id })).into_response(),
        Ok(None) => StatusCode::FORBIDDEN.into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

// --- Urgencias ---------------------------------------------------------------

async fn urgencias_cola(State(e): State<Estado>, Autenticado(u): Autenticado) -> Response {
    match urgencias::cola(&e.pool, u.ambito()).await {
        Ok(cola) => {
            // Se enriquece con la etiqueta humana del triage; el orden ya viene por
            // prioridad desde la consulta.
            let filas: Vec<serde_json::Value> = cola
                .iter()
                .map(|a| {
                    serde_json::json!({
                        "id": a.id,
                        "paciente_id": a.paciente_id,
                        "triage": a.triage,
                        "triage_label": urgencias::etiqueta_triage(&a.triage),
                        "motivo_consulta": a.motivo_consulta,
                        "fecha_ingreso": a.fecha_ingreso,
                        "estado": "EN_ESPERA",
                    })
                })
                .collect();
            // La cola atraviesa titulares y lleva el MOTIVO DE CONSULTA de cada
            // uno, que es dato clínico: `Coleccion` sin ids, la misma forma que
            // el directorio de pacientes. No hay filtro por paciente en esta
            // ruta —la cola es la cola—, así que aquí no existe el caso
            // `DeUnTitular`; inventarle uno sería un campo que nadie manda.
            registrar_coleccion(&e, &u, "listar", RECURSO_URGENCIAS, None, filas.len(), vec![]).await;
            Json(filas).into_response()
        }
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

// ── Registro de nacimiento (#249) ────────────────────────────────────────────

/// `GET /api/recien-nacidos?desde=&hasta=`
///
/// Es la ruta que hace VERDADERO el `prefijo` del módulo en el catálogo: si
/// desapareciera, `el_catalogo_no_miente_sobre_lo_que_el_binario_sirve` pondría
/// el banco en rojo en vez de dejar al producto prometiendo un módulo que no
/// sirve.
async fn recien_nacidos_listar(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Query(f): Query<RangoDeFechas>,
) -> Response {
    let desde = (!f.desde.trim().is_empty()).then(|| f.desde.trim());
    let hasta = (!f.hasta.trim().is_empty()).then(|| f.hasta.trim());
    match medico_datos::recien_nacido::listar(&e.pool, u.ambito(), desde, hasta).await {
        Ok(filas) => {
            // Igual que la cola de urgencias: colección SIN ids. Atraviesa
            // titulares y lleva la identificación de la madre.
            registrar_coleccion(
                &e,
                &u,
                "listar",
                RECURSO_RECIEN_NACIDOS,
                None,
                filas.len(),
                vec![],
            )
            .await;
            Json(filas).into_response()
        }
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

/// `POST /api/recien-nacidos`
async fn recien_nacidos_crear(
    State(e): State<Estado>,
    autorizado: Autorizado<AtenderUrgencias>,
    Json(n): Json<medico_datos::recien_nacido::Nuevo>,
) -> Response {
    let u = autorizado.0;
    match medico_datos::recien_nacido::crear(&e.pool, u.ambito(), &n, Some(u.id)).await {
        Ok(Ok(id)) => (StatusCode::CREATED, Json(Creado { id })).into_response(),
        // 422 y no 400: la petición está bien formada; lo que no cuadra es el
        // contenido, y se dice cuál con el texto del dominio.
        Ok(Err(falta)) => (
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({ "detail": falta.mensaje(), "clave": falta.clave() })),
        )
            .into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

/// El rango que comparten la lista de nacimientos y su pantalla.
#[derive(Debug, Deserialize, Default)]
struct RangoDeFechas {
    #[serde(default)]
    desde: String,
    #[serde(default)]
    hasta: String,
}

// ── Enfermería: nota, plan de cuidados, MAR y kardex (#249) ──────────────────

/// Lo que las cuatro rutas de enfermería reciben para situar al paciente.
#[derive(Debug, Deserialize)]
struct DePaciente {
    paciente_id: i64,
}

/// Lo que llega para una nota o un plan. **No trae `tipo`**, y ahí está la
/// seguridad del módulo: el tipo lo pone el servidor según el endpoint, así que
/// no hay valor que el cliente pueda mandar para escribir una epicrisis.
#[derive(Debug, Deserialize)]
struct NotaDeEnfermeria {
    paciente_id: i64,
    #[serde(default)]
    historia_id: Option<i64>,
    #[serde(default)]
    titulo: String,
    #[serde(default = "objeto_vacio_json")]
    contenido: serde_json::Value,
}

fn objeto_vacio_json() -> serde_json::Value {
    serde_json::json!({})
}

async fn crear_de_enfermeria(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    n: NotaDeEnfermeria,
    tipo: &str,
) -> Response {
    let d = medico_datos::documento::DocumentoNuevo {
        tipo: tipo.to_string(),
        paciente_id: n.paciente_id,
        historia_id: n.historia_id,
        titulo: n.titulo,
        contenido: n.contenido,
    };
    match documento::crear(&e.pool, u.ambito(), u.id, &d).await {
        Ok(Some(id)) => (StatusCode::CREATED, Json(Creado { id })).into_response(),
        Ok(None) => StatusCode::FORBIDDEN.into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

