// ── Censo diario (#249) ──────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
struct DiaDelCenso {
    #[serde(default)]
    fecha: String,
}

/// `GET /api/censo?fecha=AAAA-MM-DD`
///
/// Sin tabla: se deriva de `hospitalizacion` y `cama`, y trae `descuadres` con
/// lo que no cuadre. Un 200 con `descuadres` NO vacío es un censo que no se debe
/// firmar — se responde igual que uno bueno a propósito, porque el problema no
/// es la petición sino los datos, y esconderlo tras un error dejaría al cliente
/// sin poder ver CUÁL es.
async fn censo_del_dia(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Query(q): Query<DiaDelCenso>,
) -> Response {
    let fecha = if q.fecha.trim().is_empty() {
        medico_dominio::zona::hoy().format("%Y-%m-%d").to_string()
    } else {
        q.fecha.trim().to_string()
    };
    match medico_datos::censo::del_dia(&e.pool, u.ambito(), &fecha).await {
        Ok(Some(c)) => {
            registrar_coleccion(
                &e,
                &u,
                "listar",
                RECURSO_CENSO,
                Some(format!("censo del {fecha}")),
                c.camas_ocupadas as usize,
                vec![],
            )
            .await;
            Json(c).into_response()
        }
        // La fecha no se pudo leer. 422 y no un censo vacío, que se leería como
        // «ese día no hubo nadie» (directiva 20).
        Ok(None) => (
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "detail": "la fecha del censo va en formato AAAA-MM-DD"
            })),
        )
            .into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

