fn rechazo_pyp(f: medico_datos::pyp::Falta) -> Response {
    (
        StatusCode::UNPROCESSABLE_ENTITY,
        Json(serde_json::json!({ "detail": f.mensaje(), "clave": f.clave() })),
    )
        .into_response()
}

/// Inscribir, controlar y egresar comparten manejador; lo que cambia es el
/// PROGRAMA, y sale de la ruta. Es la misma decisión que en `/api/enfermeria/*`:
/// un programa que el cliente eligiera sería un programa que puede elegir el que
/// no tiene licenciado.
async fn pyp_inscribir_en(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    programa: &str,
    mut n: medico_datos::pyp::NuevaInscripcion,
) -> Response {
    n.programa = programa.to_string();
    match medico_datos::pyp::inscribir(&e.pool, u.ambito(), &n, Some(u.id)).await {
        Ok(Ok(id)) => (StatusCode::CREATED, Json(Creado { id })).into_response(),
        Ok(Err(f)) => rechazo_pyp(f),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

async fn pyp_controlar_en(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    programa: &str,
    n: medico_datos::pyp::NuevoControl,
) -> Response {
    // La inscripción tiene que ser DEL PROGRAMA de la ruta. Sin esto, la puerta
    // de licencia miraría `/api/pyp/vacunas` y el control caería sobre un
    // prenatal que ese cliente no compró.
    match medico_datos::pyp::es_del_programa(&e.pool, u.ambito(), n.inscripcion_id, programa).await
    {
        Ok(false) => return rechazo_pyp(medico_datos::pyp::Falta::InscripcionInexistente),
        Err(_) => return StatusCode::INTERNAL_SERVER_ERROR.into_response(),
        Ok(true) => {}
    }
    match medico_datos::pyp::controlar(&e.pool, u.ambito(), &n, u.id).await {
        Ok(Ok(id)) => (StatusCode::CREATED, Json(Creado { id })).into_response(),
        Ok(Err(f)) => rechazo_pyp(f),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

async fn pyp_egresar_en(
    e: &Estado,
    u: &medico_datos::usuario::Usuario,
    programa: &str,
    id: i64,
    motivo: &str,
) -> Response {
    match medico_datos::pyp::es_del_programa(&e.pool, u.ambito(), id, programa).await {
        Ok(false) => return rechazo_pyp(medico_datos::pyp::Falta::InscripcionInexistente),
        Err(_) => return StatusCode::INTERNAL_SERVER_ERROR.into_response(),
        Ok(true) => {}
    }
    match medico_datos::pyp::egresar(&e.pool, u.ambito(), id, motivo).await {
        Ok(Ok(())) => StatusCode::NO_CONTENT.into_response(),
        Ok(Err(f)) => rechazo_pyp(f),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

macro_rules! rutas_de_programa {
    ($inscribir:ident, $controlar:ident, $egresar:ident, $programa:expr) => {
        async fn $inscribir(
            State(e): State<Estado>,
            autorizado: Autorizado<AtenderUrgencias>,
            Json(n): Json<medico_datos::pyp::NuevaInscripcion>,
        ) -> Response {
            pyp_inscribir_en(&e, &autorizado.0, $programa, n).await
        }
        async fn $controlar(
            State(e): State<Estado>,
            autorizado: Autorizado<AtenderUrgencias>,
            Json(n): Json<medico_datos::pyp::NuevoControl>,
        ) -> Response {
            pyp_controlar_en(&e, &autorizado.0, $programa, n).await
        }
        async fn $egresar(
            State(e): State<Estado>,
            autorizado: Autorizado<AtenderUrgencias>,
            Path(id): Path<i64>,
            Json(m): Json<MotivoDeAnulacion>,
        ) -> Response {
            pyp_egresar_en(&e, &autorizado.0, $programa, id, &m.motivo).await
        }
    };
}

rutas_de_programa!(
    pyp_inscribir_prenatal,
    pyp_controlar_prenatal,
    pyp_egresar_prenatal,
    "PRENATAL"
);
rutas_de_programa!(
    pyp_inscribir_crecimiento,
    pyp_controlar_crecimiento,
    pyp_egresar_crecimiento,
    "CRECIMIENTO_DESARROLLO"
);
rutas_de_programa!(
    pyp_inscribir_reproductiva,
    pyp_controlar_reproductiva,
    pyp_egresar_reproductiva,
    "SALUD_REPRODUCTIVA"
);

