/// `GET /api/habilitacion/indicadores?desde=&hasta=`
///
/// Trae `no_calculables` con lo que este producto todavía no puede medir y qué
/// le falta. Es la mitad del valor de la respuesta.
async fn hab_indicadores(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Query(f): Query<RangoDeFechas>,
) -> Response {
    let hoy = medico_dominio::zona::hoy().format("%Y-%m-%d").to_string();
    let desde = if f.desde.trim().is_empty() {
        format!("{}-01", &hoy[..7])
    } else {
        f.desde.trim().to_string()
    };
    let hasta = if f.hasta.trim().is_empty() {
        hoy
    } else {
        f.hasta.trim().to_string()
    };
    match medico_datos::indicadores::del_periodo(&e.pool, u.ambito(), &desde, &hasta).await {
        Ok(Some(v)) => Json(v).into_response(),
        Ok(None) => StatusCode::FORBIDDEN.into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

