async fn nutri_crear(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirNutricion>,
    Json(v): Json<ValoracionCrear>,
) -> Response {
    let u = autorizado.0;
    match nutricion::crear_valoracion(&e.pool, u.ambito(), u.id, &v).await {
        Ok(nutricion::Alta::Creada(id)) => {
            match nutricion::obtener_valoracion(&e.pool, u.ambito(), id).await {
                Ok(Some(val)) => (StatusCode::CREATED, Json(val)).into_response(),
                _ => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
            }
        }
        Ok(nutricion::Alta::NoVisible) => StatusCode::FORBIDDEN.into_response(),
        // 400 y no 403: la petición se puede corregir, y decir «no le
        // corresponde» mandaría a pedir un permiso a quien lo que tiene es un
        // cero en la báscula.
        Ok(nutricion::Alta::SinAntropometria) => detalle(
            StatusCode::BAD_REQUEST,
            "La valoración necesita peso y talla: el índice de masa corporal se calcula a \
             partir de ellos y no se recibe."
                .into(),
        ),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

