// --- Fórmulas (prescripciones de una historia) -------------------------------

async fn listar_formulas(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Path(historia_id): Path<i64>,
) -> Result<Json<Vec<Formula>>, StatusCode> {
    formula::listar_por_historia(&e.pool, u.ambito(), historia_id)
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

async fn crear_formula(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirClinico>,
    Path(historia_id): Path<i64>,
    Json(f): Json<FormulaNueva>,
) -> Response {
    let u = autorizado.0;
    // #84: el cuerpo JSON no puede afirmar procedencia — no hay humano tocando un
    // control aquí, y dejarle mandar «confirmado» convertiría la procedencia en lo
    // que el cliente dice de sí mismo.
    //
    // Mapa vacío = columna `{}` = el recolector SÍ audita la fila, y la marca
    // ENTERA porque nadie afirmó nada. Aquí ponía «= columna `NULL` = el recolector
    // salta la fila, igual que antes de la 0060», y llevaba siendo falso desde
    // `6d44fab5`: `json_de` devuelve siempre `Some`. Describía el comportamiento
    // inseguro que se acababa de arreglar, en la línea exacta donde alguien iría a
    // decidir si esta ruta hay que cerrarla. Lo cazó la revisión de la directiva 25.
    match formula::crear(&e.pool, u.ambito(), historia_id, &f, &Default::default()).await {
        Ok(medico_datos::Creacion::Creada(id)) => {
            (StatusCode::CREATED, Json(Creado { id })).into_response()
        }
        Ok(medico_datos::Creacion::NoExiste) => StatusCode::FORBIDDEN.into_response(),
        Ok(medico_datos::Creacion::Firmada) => detalle(
            StatusCode::CONFLICT,
            "Esta historia está firmada: no se le añade ni se le quita nada. Un documento \
             firmado no se edita por ninguna puerta — se corrige emitiendo otro."
                .to_string(),
        ),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

async fn actualizar_formula(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirClinico>,
    Path(id): Path<i64>,
    Json(f): Json<FormulaNueva>,
) -> StatusCode {
    let u = autorizado.0;
    // #84: igual que al crear, y aquí además BORRA la procedencia que hubiera —
    // editar el CUM invalida el aval que alguien dio sobre el anterior.
    match formula::actualizar(&e.pool, u.ambito(), id, &f, &Default::default()).await {
        Ok(medico_datos::Resultado::Hecho) => StatusCode::NO_CONTENT,
        Ok(medico_datos::Resultado::NoExiste) => StatusCode::NOT_FOUND,
        // 409: existe y es suya, pero su historia está cerrada.
        Ok(medico_datos::Resultado::Firmada) => StatusCode::CONFLICT,
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

async fn eliminar_formula(
    State(e): State<Estado>,
    autorizado: Autorizado<EscribirClinico>,
    Path(id): Path<i64>,
) -> Response {
    let u = autorizado.0;
    match formula::eliminar(&e.pool, u.ambito(), id).await {
        Ok(formula::ResultadoBorrado::Hecho) => StatusCode::NO_CONTENT.into_response(),
        Ok(formula::ResultadoBorrado::NoExiste) => StatusCode::NOT_FOUND.into_response(),
        Ok(formula::ResultadoBorrado::HistoriaFirmada) => detalle(
            StatusCode::CONFLICT,
            "Esta historia está firmada: no se le añade ni se le quita nada. Un documento \
             firmado no se edita por ninguna puerta — se corrige emitiendo otro."
                .to_string(),
        ),
        Ok(formula::ResultadoBorrado::YaDispensada { entregas }) => detalle(
            StatusCode::CONFLICT,
            format!(
                "Esta fórmula ya tiene {entregas} entrega(s) registradas en farmacia: borrarla \
                 dejaría la dispensación sin prescripción que la respalde. Corríjala con una \
                 fórmula nueva."
            ),
        ),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

