#[derive(Deserialize)]
struct CambioEstado {
    estado: String,
}

/// `PUT /api/citas/{id}/estado` — confirmar, cancelar o marcar la asistencia.
///
/// **La cita PROPIA, o `GestionarAgenda`.** La exención que dejaba esta ruta sin
/// capacidad decía literalmente «confirmar o cancelar la cita propia», y hasta
/// el 2026-08-10 no comprobaba nada más que la institución: cualquier cuenta
/// activa cancelaba la cita de cualquier paciente iterando ids. La revisión de
/// seguridad midió que la palabra «propia» no la sostenía ninguna línea.
///
/// «Propia» solo puede significar hoy **el profesional al que está asignada**:
/// no hay columna que ate una cuenta a una fila de `paciente`, así que el
/// paciente titular no es identificable desde la sesión. Se dice en vez de
/// fabricar una comprobación que no puede funcionar (directiva 20). Quien no es
/// el profesional necesita `GestionarAgenda`, que es la capacidad de recepción.
async fn cambiar_estado_cita(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Path(id): Path<i64>,
    Json(req): Json<CambioEstado>,
) -> StatusCode {
    let suya = match cita::profesional_de(&e.pool, u.ambito(), id).await {
        Ok(m) => m == Some(u.id),
        Err(_) => return StatusCode::INTERNAL_SERVER_ERROR,
    };
    if !suya {
        let permitido = match (u.rol(), u.ambito()) {
            (Some(rol), Ambito::Institucion(inst)) => {
                match e.capacidades.ajustes(&e.pool, inst).await {
                    Ok(a) => a.puede(rol, medico_dominio::rol::Capacidad::GestionarAgenda),
                    // Si la matriz no se puede leer es avería, no un permiso
                    // recortado.
                    Err(_) => return StatusCode::SERVICE_UNAVAILABLE,
                }
            }
            (Some(_), Ambito::Superadmin) => true,
            _ => false,
        };
        if !permitido {
            // 404 y no 403: un 403 confirmaría que esa cita existe, y con eso se
            // enumera la agenda del prestador. Es la regla de este repositorio.
            return StatusCode::NOT_FOUND;
        }
    }
    match cita::cambiar_estado(&e.pool, u.ambito(), id, &req.estado).await {
        Ok(true) => StatusCode::NO_CONTENT,
        Ok(false) => StatusCode::NOT_FOUND,
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

