async fn img_ordenes(
    State(e): State<Estado>,
    Autenticado(u): Autenticado,
    Query(f): Query<FiltroOrdenesDx>,
) -> Response {
    match diagnostico::listar_ordenes(
        &e.pool, u.ambito(), diagnostico::Servicio::Imagenologia,
        f.estado.as_deref(), f.paciente_id,
    ).await {
        Ok(os) => {
            // **La bandeja atraviesa pacientes y devuelve NOMBRE y DOCUMENTO**
            // de cada uno (`columnas_orden`), así que es exactamente la misma
            // forma que `/api/pacientes`: `Coleccion`, sin ids —ver un nombre en
            // una lista no es abrir el expediente— y también cuando devuelve
            // cero, porque un barrido que no encontró nada también se hizo.
            //
            // Con `paciente_id` en el filtro es el expediente de imagenología de
            // UNA persona identificada en la petición, y ahí la forma es
            // `DeUnTitular` — la misma regla que separa `/api/documentos` con
            // filtro de `/api/documentos` sin él.
            match f.paciente_id {
                Some(pid) => {
                    registrar_coleccion_de_un_titular(
                        &e, &u, "listar", RECURSO_ORDENES_IMAGEN, pid,
                        f.estado.clone(), os.len(),
                    )
                    .await;
                }
                None => {
                    registrar_coleccion(
                        &e, &u, "listar", RECURSO_ORDENES_IMAGEN,
                        f.estado.clone(), os.len(), vec![],
                    )
                    .await;
                }
            }
            Json(os).into_response()
        }
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

async fn img_orden(State(e): State<Estado>, Autenticado(u): Autenticado, Path(id): Path<i64>) -> Response {
    match diagnostico::obtener_orden(&e.pool, u.ambito(), diagnostico::Servicio::Imagenologia, id).await {
        Ok(Some(o)) => {
            // `Recurso`: una orden identificada, con el nombre y el documento de
            // su paciente dentro. Es una apertura, no un barrido, así que va con
            // los dos ids — y entra en el rastro que el titular puede pedir.
            // `paciente_id` es `Option` en el tipo y la consulta lo saca de un
            // JOIN con `paciente`, así que no puede faltar. Si faltara, NO se
            // rellena con nada (directiva 20): se grita, porque un eslabón con
            // un titular inventado es peor que uno que falta.
            match o.paciente_id {
                Some(pid) => registrar_acceso(&e, &u, "ver", RECURSO_ORDEN_IMAGEN, id, pid).await,
                None => eprintln!(
                    "⚠️  bitácora: la orden de imagenología {id} salió sin paciente_id; \
                     no se anotó el acceso"
                ),
            }
            Json(o).into_response()
        }
        Ok(None) => StatusCode::NOT_FOUND.into_response(),
        Err(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

