        /// LA BITÁCORA DEL PANEL, cableada el 2026-08-10.
        ///
        /// No basta con que anote: tiene que anotar **lo mismo** que su gemelo
        /// de `/api`, o el rastro de un mismo hecho queda partido en dos según
        /// por qué puerta se hizo — que es exactamente lo que este repositorio
        /// ya cerró para los cinco listados clínicos.
        #[tokio::test]
        async fn el_panel_anota_el_acto_administrativo_igual_que_la_api() {
            let e = con_admin_y_lab().await;

            let eslabones = |e: Estado| async move {
                let filas: Vec<(String,)> = sqlx::query_as(
                    "SELECT contenido FROM acceso ORDER BY secuencia ASC",
                )
                .fetch_all(&e.pool)
                .await
                .unwrap();
                filas
                    .into_iter()
                    .map(|(c,)| serde_json::from_str::<serde_json::Value>(&c).unwrap())
                    .collect::<Vec<_>>()
            };

            // Por el PANEL: cambiar la política de seguridad.
            let r = router(e.clone())
                .oneshot(
                    Request::builder()
                        .method("POST")
                        .uri("/panel/admin/seguridad")
                        .header(header::COOKIE, cookie_de(ADMIN))
                        .header(header::CONTENT_TYPE, "application/x-www-form-urlencoded")
                        .body(Body::from("longitud_minima_password=12&requiere_numero=1"))
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_ne!(r.status(), StatusCode::SERVICE_UNAVAILABLE);

            let del_panel = eslabones(e.clone()).await;
            assert_eq!(del_panel.len(), 1, "{del_panel:?}");
            assert_eq!(del_panel[0]["accion"], "configurar");
            assert_eq!(del_panel[0]["recurso"], "politica_seguridad");

            // Por la API, el mismo acto: el eslabón tiene que decir lo mismo.
            let e2 = con_admin_y_lab().await;
            let r = enviar(
                &e2,
                "PUT",
                "/api/admin/politica-seguridad",
                ADMIN,
                r#"{"longitud_minima_password":12}"#,
            )
            .await;
            assert!(r.status().is_success(), "{}", cuerpo_de(r).await);
            let de_la_api = eslabones(e2).await;
            assert_eq!(de_la_api.len(), 1);

            assert_eq!(
                (del_panel[0]["accion"].clone(), del_panel[0]["recurso"].clone(),
                 del_panel[0]["alcance"]["filtro"].clone()),
                (de_la_api[0]["accion"].clone(), de_la_api[0]["recurso"].clone(),
                 de_la_api[0]["alcance"]["filtro"].clone()),
                "las dos puertas tienen que describir el MISMO acto"
            );
        }

