        #[tokio::test]
        async fn los_catalogos_de_la_948_se_sirven_para_que_la_pantalla_los_ofrezca() {
            // Existen porque hasta el 2026-08-02 la pantalla NO podía ofrecer
            // estos dos campos, así que el sistema los rellenaba solo — y con
            // códigos de la tabla anterior, que el validador rechaza.
            let e = con_admin_y_una_consulta().await;

            let r = enviar(&e, "/api/finalidades", ADMIN).await;
            assert_eq!(r.status(), StatusCode::OK);
            let v = cuerpo(r).await;
            let fs = v.as_array().unwrap();
            assert_eq!(fs.len(), 34);
            assert_eq!(fs[0]["codigo"], "11", "la tabla de la 948 empieza en 11");
            assert!(fs.iter().all(|f| f["codigo"] != "10"), "el «10» ya no está");
            // Con `aplica_ac`, para que la consulta no ofrezca las de solo AP.
            assert!(fs.iter().any(|f| f["aplica_ac"] == false));

            let r = enviar(&e, "/api/causas-motivo", ADMIN).await;
            assert_eq!(r.status(), StatusCode::OK);
            let v = cuerpo(r).await;
            let cs = v.as_array().unwrap();
            assert_eq!(cs.len(), 29);
            assert!(cs.iter().all(|c| c["codigo"] != "13"), "el «13» ya no está");
            let g = cs.iter().find(|c| c["codigo"] == "38").unwrap();
            assert_eq!(g["nombre"], "ENFERMEDAD GENERAL");
        }

        /// **La finalidad contra el CUPS del servicio (#331), por la ruta.**
        ///
        /// `muv.rs` prueba la regla y `ac.rs` que el archivo la ejerza. Lo que
        /// aquí importa es que la PANTALLA pueda usarla: sin esto, el endpoint
        /// podría ignorar el parámetro y todo lo demás seguiría verde.
        ///
        /// Los tres estados, con sus tres casos:
        #[tokio::test]
        async fn las_finalidades_se_anotan_contra_el_cups_de_la_consulta() {
            let e = con_admin_y_una_consulta().await;

            // 1. SIN `cups`: no se preguntó, así que no se sabe. Y siguen siendo
            //    las 34 con su forma de siempre — el contrato no se rompió.
            let v = cuerpo(enviar(&e, "/api/finalidades", ADMIN).await).await;
            let fs = v.as_array().unwrap();
            assert_eq!(fs.len(), 34);
            assert!(
                fs.iter().all(|f| f["admitida_para_cups"].is_null()),
                "sin preguntar por un CUPS no se puede afirmar nada"
            );

            // 2. CUPS CUBIERTO: la tabla habla, y aprieta de 34 a 9.
            let v = cuerpo(enviar(&e, "/api/finalidades?cups=890201", ADMIN).await).await;
            let fs = v.as_array().unwrap();
            assert_eq!(fs.len(), 34, "se anotan todas, no se filtran");
            let si: Vec<&str> = fs
                .iter()
                .filter(|f| f["admitida_para_cups"] == true)
                .map(|f| f["codigo"].as_str().unwrap())
                .collect();
            assert_eq!(
                si,
                ["11", "19", "20", "23", "24", "25", "27", "40", "42"],
                "890201 admite nueve finalidades"
            );
            // Y la otra mitad: las que NO valen se dicen `false`, no `null`. Sin
            // esto, una respuesta que pusiera `null` en todo pasaría el caso 1 y
            // parecería que discrimina.
            assert!(
                fs.iter().any(|f| f["admitida_para_cups"] == false),
                "ninguna se marcó como rechazada: no se está contrastando nada"
            );

            // 3. CUPS QUE LA TABLA NO CUBRE —el 97,74 % del catálogo—: **null**,
            //    y no `false`. Es la línea que impide que la pantalla se quede
            //    sin opciones que ofrecer para casi cualquier procedimiento.
            let v = cuerpo(enviar(&e, "/api/finalidades?cups=890202", ADMIN).await).await;
            let fs = v.as_array().unwrap();
            assert!(
                fs.iter().all(|f| f["admitida_para_cups"].is_null()),
                "un CUPS ausente de la tabla se trató como rechazo: la pantalla se \
                 quedaría sin ninguna finalidad que ofrecer"
            );

            // Y un CUPS inventado va por el mismo camino: no se sabe.
            let v = cuerpo(enviar(&e, "/api/finalidades?cups=ZZZZZZ", ADMIN).await).await;
            assert!(
                v.as_array().unwrap().iter().all(|f| f["admitida_para_cups"].is_null()),
                "un CUPS inexistente no puede producir un veredicto"
            );
        }

        /// **El CUPS de la consulta, capturable y validado (#331, prerrequisito).**
        ///
        /// Hasta hoy `cod_consulta_cups` viajaba al RIPS y NINGUNA pantalla lo
        /// capturaba: en todo el frontal el nombre aparecía una vez, dentro de
        /// un comentario. Sin buscador no hay forma de elegirlo entre 13 640, y
        /// sin puerta en la escritura el buscador es una cortesía.
        #[tokio::test]
        async fn el_cups_de_la_consulta_se_busca_acotado_y_se_valida_al_escribir() {
            let e = con_admin_y_una_consulta().await;
            // El catálogo clínico no lo siembra el fixture —son 26 063 filas y
            // costarían en cada prueba—, así que aquí entran las tres que este
            // caso necesita, con sus tres ámbitos.
            sqlx::query(
                "INSERT INTO cups (codigo, nombre, seccion, ambito_rips, quirurgico) VALUES
                 ('890201','CONSULTA DE PRIMERA VEZ MEDICINA GENERAL','CONSULTA','AC',0),
                 ('471001','ARTROSCOPIA DE RODILLA','QUIRURGICO','AP',1),
                 ('999999','TRASLADO ASISTENCIAL','OTROS','AT',0)",
            )
            .execute(&e.pool)
            .await
            .unwrap();

            // El buscador acota por ámbito: para una CONSULTA, solo los del AC.
            let r = enviar(&e, "/api/cups/buscar?q=890201&ambito=AC", ADMIN).await;
            assert_eq!(r.status(), StatusCode::OK);
            let v = cuerpo(r).await;
            let hay = v.as_array().unwrap();
            assert!(!hay.is_empty(), "no se encontró el CUPS de consulta más común");
            assert!(
                hay.iter().all(|c| c["ambito_rips"] == "AC"),
                "el buscador ofreció códigos de otro archivo del RIPS"
            );

            // **Sin `ambito` es 400 y no una lista vacía.** Vacío se lee como
            // «ese procedimiento no existe», y quien lo lea así se inventará el
            // código o dejará el defecto — que es de donde venimos.
            let r = enviar(&e, "/api/cups/buscar?q=890201", ADMIN).await;
            assert_eq!(
                r.status(),
                StatusCode::BAD_REQUEST,
                "sin ámbito se devolvió algo en vez de decir que falta"
            );

            // Y un ámbito inventado tampoco cae a un defecto.
            let r = enviar(&e, "/api/cups/buscar?q=890201&ambito=consultas", ADMIN).await;
            assert_eq!(r.status(), StatusCode::BAD_REQUEST);

            // ── LA ESCRITURA ────────────────────────────────────────────────
            //
            // El filtro del buscador es cortesía de pantalla: sin puerta aquí,
            // el cuerpo mete cualquier cadena. Es la misma razón por la que
            // `medico_id` se valida aunque el selector solo muestre los propios.
            // Escribe la MÉDICA (usuario 2 del fixture), no el admin:
            // `EscribirClinico` es capacidad clínica y el admin no la trae.
            let escribir = |cuerpo: &'static str| {
                let e = e.clone();
                async move {
                    router(e)
                        .oneshot(
                            Request::builder()
                                .method("POST")
                                .uri("/api/historias")
                                .header(header::COOKIE, cookie_de(2))
                                .header(header::CONTENT_TYPE, "application/json")
                                .body(Body::from(cuerpo))
                                .unwrap(),
                        )
                        .await
                        .unwrap()
                        .status()
                }
            };
            const BASE: &str = r#""paciente_id":10,"medico_id":2,"motivo_consulta":"x","enfermedad_actual":"y","diagnostico_principal":"J00","plan_tratamiento":"z""#;

            // El CUPS de CONSULTA entra.
            assert_eq!(
                escribir(concat!(r#"{"#, r#""paciente_id":10,"medico_id":2,"motivo_consulta":"x","enfermedad_actual":"y","diagnostico_principal":"J00","plan_tratamiento":"z""#, r#","cod_consulta_cups":"890201"}"#)).await,
                StatusCode::CREATED,
                "el CUPS de consulta correcto fue rechazado: cierra de más"
            );

            // EL DE PROCEDIMIENTOS NO, aunque exista: el MUV lo rechazaría en el
            // archivo de consultas, semanas después y sobre la factura del mes.
            assert_eq!(
                escribir(concat!(r#"{"#, r#""paciente_id":10,"medico_id":2,"motivo_consulta":"x","enfermedad_actual":"y","diagnostico_principal":"J00","plan_tratamiento":"z""#, r#","cod_consulta_cups":"471001"}"#)).await,
                StatusCode::UNPROCESSABLE_ENTITY,
                "un CUPS de PROCEDIMIENTOS entró como consulta"
            );

            // Ni uno inventado.
            assert_eq!(
                escribir(concat!(r#"{"#, r#""paciente_id":10,"medico_id":2,"motivo_consulta":"x","enfermedad_actual":"y","diagnostico_principal":"J00","plan_tratamiento":"z""#, r#","cod_consulta_cups":"NOEXISTE"}"#)).await,
                StatusCode::UNPROCESSABLE_ENTITY
            );

            // Y SIN CUPS sigue entrando: el campo es opcional, y que falte es
            // una falta que el cierre anota — mejor que un «890201» que nadie
            // eligió, que es de donde venimos.
            assert_eq!(
                escribir(concat!(r#"{"#, r#""paciente_id":10,"medico_id":2,"motivo_consulta":"x","enfermedad_actual":"y","diagnostico_principal":"J00","plan_tratamiento":"z""#, r#"}"#)).await,
                StatusCode::CREATED,
                "exigir el CUPS habría bloqueado la captura de una historia"
            );
            let _ = BASE;
        }

        #[tokio::test]
